            .
          </p>
        </div>
      )}

      {data && data.errors.length > 0 && (
        <div className="mb-6 glass-surface rounded-lg px-5 py-3 text-xs text-[#64717a]">
          {data.errors.join(" ")}
        </div>
      )}

      {loading && !data ? (
