                <div className="overflow-x-auto">
                  <table className="w-full min-w-[560px] text-sm">
                    <thead>
                      <tr className="border-b border-[#242526]/8">
                        <Th>Name</Th>
                        <Th>Email</Th>
                        <Th>Sign-in</Th>
                        <Th align="right">Joined</Th>
                      </tr>
                    </thead>
                    <tbody>
                      {(data?.users.recent ?? [])
                        .slice(0, signupsShown)
