"use client";
import {providerMutationFetch} from "@/lib/affiliates/provider-mutation-fetch";

import { useCallback, useEffect, useMemo, useState } from "react";
import {
  Users,
  Search,
  X,
  Loader2,
  Send,
  CheckCircle2,
  AlertCircle,
  Mail,
} from "lucide-react";
import {
  PageHeader,
  EmptyState,
  formatCurrency,
  formatShortDate,
} from "@/components/affiliates/shared/ui";

interface Customer {
  email: string;
  name: string;
  firstName: string;
  orderCount: number;
  totalSpent: number;
  currency: string;
  lastOrderDate: string;
}

interface SendResult {
  sent: number;
  failed: number;
  total: number;
  mode: string;
}

export default function AdminCustomersPage() {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [truncated, setTruncated] = useState(false);
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState<Set<string>>(new Set());

  const [subject, setSubject] = useState("");
  const [message, setMessage] = useState("");
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<SendResult | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/affiliates/admin/customers", {
        credentials: "include",
      });
      if (res.ok) {
        const data = await res.json();
        setCustomers(data.customers ?? []);
        setTruncated(Boolean(data.truncated));
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const visible = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return customers;
    return customers.filter((c) =>
      [c.name, c.email].some((v) => v.toLowerCase().includes(q))
    );
  }, [customers, search]);

  const visibleEmails = useMemo(
    () => visible.map((c) => c.email),
    [visible]
  );
  const allVisibleSelected =
    visibleEmails.length > 0 && visibleEmails.every((e) => selected.has(e));

  const toggle = useCallback((email: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(email)) next.delete(email);
      else next.add(email);
      return next;
    });
  }, []);

  const toggleAllVisible = useCallback(() => {
    setSelected((prev) => {
      const next = new Set(prev);
      const allSelected = visibleEmails.every((e) => next.has(e));
      if (allSelected) {
        for (const e of visibleEmails) next.delete(e);
      } else {
        for (const e of visibleEmails) next.add(e);
      }
      return next;
    });
  }, [visibleEmails]);

  const clearSelection = useCallback(() => setSelected(new Set()), []);

  const send = useCallback(async () => {
    if (sending) return;
    setError(null);
    setResult(null);
    if (selected.size === 0) {
      setError("Select at least one customer.");
      return;
    }
    if (!subject.trim()) {
      setError("Add a subject.");
      return;
    }
    if (!message.trim()) {
      setError("Write a message.");
      return;
    }
    if (
      !window.confirm(
        `Send this email to ${selected.size} ${
          selected.size === 1 ? "customer" : "customers"
        }?`
      )
    ) {
      return;
    }

    setSending(true);
    try {
      const recipients = customers
        .filter((c) => selected.has(c.email))
        .map((c) => ({ email: c.email, firstName: c.firstName }));
      const res = await providerMutationFetch("/api/affiliates/admin/customers/email", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          subject: subject.trim(),
          message: message.trim(),
          recipients,
        }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data?.ok === false) {
        setError(data?.error?.message || data?.error || "Could not send emails.");
        return;
      }
      setResult({
        sent: data.sent ?? 0,
        failed: data.failed ?? 0,
        total: data.total ?? 0,
        mode: data.mode ?? "resend",
      });
      setSubject("");
      setMessage("");
      setSelected(new Set());
    } catch {
      setError("Could not send emails. Please try again.");
    } finally {
      setSending(false);
    }
  }, [sending, selected, subject, message, customers]);

  return (
    <>
      <PageHeader
        eyebrow="Outreach"
        title="Customers"
        description="Everyone who's placed an order. Pick who to reach out to, write your message, and send — each customer gets their own personalized copy."
        actions={
