type MessageStatus = "new" | "read" | "replied" | "archived";

interface ContactMessage {
  id: string;
  name: string;
  email: string;
  subject: string | null;
  message: string;
  status: MessageStatus;
  readAt: string | null;
  repliedAt?: string | null;
  createdAt: string;
}

const SUBJECT_LABELS: Record<string, string> = {
  order: "Order inquiry",
  coa: "COA request",
  general: "General inquiry",
  other: "Other",
};

function subjectLabel(subject: string | null): string {
  if (!subject) return "No subject";
  return SUBJECT_LABELS[subject] ?? subject;
}

type Filter = "all" | "new" | "archived";

interface PendingAttachment {
  filename: string;
  contentType: string;
  /** Base64 file content (no data-URL prefix), as the reply API expects. */
  content: string;
  size: number;
  /** Object URL for image thumbnails; null for non-images. */
  previewUrl: string | null;
}

const MAX_REPLY_ATTACHMENTS = 5;
const MAX_REPLY_ATTACHMENT_BYTES = 3 * 1024 * 1024;

function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function readFileAsBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = String(reader.result ?? "");
      resolve(result.slice(result.indexOf(",") + 1));
    };
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(file);
  });
}

type Section = "inbox" | "marketing";

export default function AdminMessagesPage() {
  const [section, setSection] = useState<Section>("inbox");
  const [messages, setMessages] = useState<ContactMessage[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<Filter>("all");
  const [active, setActive] = useState<ContactMessage | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/affiliates/admin/messages", {
        credentials: "include",
      });
      if (res.ok) {
        const data = await res.json();
        setMessages(data.messages ?? []);
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const updateStatus = useCallback(
    async (id: string, status: MessageStatus) => {
      setMessages((prev) =>
        prev.map((m) =>
          m.id === id
            ? { ...m, status, readAt: status === "new" ? null : new Date().toISOString() }
            : m
        )
      );
      setActive((cur) => (cur && cur.id === id ? { ...cur, status } : cur));
      await fetch(`/api/affiliates/admin/messages/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ status }),
      }).catch(() => {});
    },
    []
  );

  const removeMessage = useCallback(async (id: string) => {
    if (!window.confirm("Delete this message permanently?")) return;
    try {
      const response = await nonproviderMutationFetch(`/api/affiliates/admin/messages/${id}`, {
        method: "DELETE",
        credentials: "include",
      });
      if (!response.ok) return;
      setMessages((prev) => prev.filter((m) => m.id !== id));
      setActive((cur) => (cur && cur.id === id ? null : cur));
    } catch {
      // Keep the original control and operation UUID for an unchanged retry.
    }
  }, []);

  function openMessage(m: ContactMessage) {
    setActive(m);
    if (m.status === "new") updateStatus(m.id, "read");
  }

  const unreadCount = useMemo(
    () => messages.filter((m) => m.status === "new").length,
    [messages]
  );

  const visible = useMemo(() => {
    if (filter === "new") return messages.filter((m) => m.status === "new");
    if (filter === "archived")
      return messages.filter((m) => m.status === "archived");
    return messages.filter((m) => m.status !== "archived");
  }, [messages, filter]);

  const filters: { key: Filter; label: string; count: number }[] = [
    {
      key: "all",
      label: "Inbox",
      count: messages.filter((m) => m.status !== "archived").length,
    },
    { key: "new", label: "Unread", count: unreadCount },
    {
      key: "archived",
      label: "Archived",
      count: messages.filter((m) => m.status === "archived").length,
    },
  ];

  return (
    <>
      <PageHeader
        eyebrow="Contact"
        title={section === "inbox" ? "Contact messages" : "Email marketing"}
        description={
          section === "inbox"
            ? "Everything submitted through the public Contact form lands here."
            : "Reach people who signed up but never ordered. Start a drip campaign and a batch goes out every day."
        }
        actions={
          section === "inbox" ? (
            <span className="inline-flex items-center gap-2 glass-surface rounded-full px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
              <Mail className="h-3.5 w-3.5" />
              {unreadCount} unread
            </span>
          ) : undefined
        }
      />

      <div className="flex flex-wrap gap-2 mb-5">
        {(
          [
            { key: "inbox" as Section, label: "Inbox", icon: Inbox },
            { key: "marketing" as Section, label: "Email marketing", icon: Megaphone },
          ]
        ).map((s) => (
          <button
            key={s.key}
            onClick={() => setSection(s.key)}
            className={`inline-flex items-center gap-2 rounded-full px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans transition-colors ${
              section === s.key
                ? "bg-[#242526] text-white"
                : "glass-surface text-[#64717a] hover:text-[#20282c]"
            }`}
          >
            <s.icon className="h-3.5 w-3.5" />
            {s.label}
          </button>
        ))}
      </div>

      {section === "marketing" && <EmailMarketingTab />}

      {section === "inbox" && (
        <>
      <div className="flex flex-wrap gap-2 mb-5">
        {filters.map((f) => (
          <button
            key={f.key}
            onClick={() => setFilter(f.key)}
            className={`inline-flex items-center gap-2 rounded-full px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans transition-colors ${
              filter === f.key
                ? "bg-[#242526] text-white"
                : "glass-surface text-[#64717a] hover:text-[#20282c]"
            }`}
          >
            {f.label}
            <span
              className={`px-1.5 py-0.5 rounded-full leading-none ${
                filter === f.key ? "bg-white/15 text-white" : "bg-[#242526]/8 text-[#64717a]"
              }`}
            >
              {f.count}
            </span>
          </button>
        ))}
      </div>

      {loading ? (
        <div className="glass-surface rounded-lg p-12 text-center text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
          Loading…
        </div>
      ) : visible.length === 0 ? (
        <EmptyState
          icon={Inbox}
          title="Nothing here"
          description={
            filter === "archived"
              ? "No archived messages."
              : "No messages yet. Submissions from the Contact page will appear here."
          }
        />
      ) : (
        <ul className="space-y-3">
          {visible.map((m) => {
            const unread = m.status === "new";
            return (
              <li key={m.id}>
                <button
                  onClick={() => openMessage(m)}
                  className="w-full text-left glass-surface rounded-lg p-5 sm:p-6 flex items-start gap-4 hover:bg-[#242526]/[0.03] transition-colors"
                >
                  <div
                    className={`mt-0.5 w-9 h-9 shrink-0 rounded-full flex items-center justify-center ${
                      unread ? "bg-[#242526] text-white" : "bg-[#242526]/6 text-[#64717a]"
                    }`}
                  >
                    {unread ? (
                      <Mail className="h-4 w-4" />
                    ) : (
                      <MailOpen className="h-4 w-4" />
                    )}
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center justify-between gap-3">
                      <h3
                        className={`truncate ${
                          unread ? "font-semibold text-[#20282c]" : "font-medium text-[#20282c]"
                        }`}
                      >
                        {m.name}
                      </h3>
                      <span className="shrink-0 text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
                        {formatShortDate(m.createdAt)}
                      </span>
                    </div>
                    <p className="text-sm text-[#64717a] truncate mt-0.5">
                      {m.email}
                    </p>
                    <div className="flex items-center gap-2 mt-2">
                      <Pill tone={unread ? "dark" : "neutral"}>
                        {subjectLabel(m.subject)}
                      </Pill>
                      {m.status === "replied" && (
                        <Pill tone="success">Replied</Pill>
                      )}
                      {m.status === "archived" && (
                        <Pill tone="warn">Archived</Pill>
                      )}
                    </div>
                    <p className="text-sm text-[#20282c]/80 mt-3 line-clamp-2">
                      {m.message}
                    </p>
                  </div>
                </button>
              </li>
            );
          })}
        </ul>
      )}

      {active && (
        <MessageDrawer
          message={active}
          onClose={() => setActive(null)}
          onArchive={() =>
            updateStatus(
              active.id,
              active.status === "archived" ? "read" : "archived"
            )
          }
          onDelete={() => removeMessage(active.id)}
          onReplied={() => {
            // The reply endpoint already marks the row as replied server-side;
            // mirror that locally without another PATCH.
            const now = new Date().toISOString();
            setMessages((prev) =>
              prev.map((m) =>
                m.id === active.id
                  ? { ...m, status: "replied", readAt: m.readAt ?? now, repliedAt: now }
                  : m
              )
            );
            setActive((cur) =>
              cur && cur.id === active.id ? { ...cur, status: "replied" } : cur
            );
          }}
        />
      )}
        </>
      )}
    </>
  );
}

function MessageDrawer({
  message,
  onClose,
  onArchive,
  onDelete,
  onReplied,
}: {
  message: ContactMessage;
  onClose: () => void;
  onArchive: () => void;
  onDelete: () => void;
  onReplied: () => void;
}) {
  const [composing, setComposing] = useState(false);
  const [reply, setReply] = useState("");
  const [sending, setSending] = useState(false);
  const [sent, setSent] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [attachments, setAttachments] = useState<PendingAttachment[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Revoke image preview object URLs when the drawer unmounts.
  useEffect(() => {
    return () => {
      setAttachments((prev) => {
        prev.forEach((a) => a.previewUrl && URL.revokeObjectURL(a.previewUrl));
        return prev;
      });
    };
  }, []);

  const addFiles = useCallback(
    async (files: FileList | null) => {
      if (!files || files.length === 0) return;
      setError(null);

      const current = [...attachments];
      let totalBytes = current.reduce((acc, a) => acc + a.size, 0);

      for (const file of Array.from(files)) {
        if (current.length >= MAX_REPLY_ATTACHMENTS) {
          setError(`Up to ${MAX_REPLY_ATTACHMENTS} attachments per reply.`);
          break;
        }
        if (totalBytes + file.size > MAX_REPLY_ATTACHMENT_BYTES) {
          setError("Attachments are too large — 3MB total max.");
          break;
        }
        try {
          const content = await readFileAsBase64(file);
          current.push({
            filename: file.name,
            contentType: file.type || "application/octet-stream",
            content,
            size: file.size,
            previewUrl: file.type.startsWith("image/")
              ? URL.createObjectURL(file)
              : null,
          });
          totalBytes += file.size;
        } catch {
          setError(`Could not read "${file.name}".`);
        }
      }
      setAttachments(current);
      if (fileInputRef.current) fileInputRef.current.value = "";
    },
    [attachments]
  );

  const removeAttachment = useCallback((index: number) => {
    setAttachments((prev) => {
      const target = prev[index];
      if (target?.previewUrl) URL.revokeObjectURL(target.previewUrl);
      return prev.filter((_, i) => i !== index);
    });
  }, []);

  const sendReply = useCallback(async () => {
    const text = reply.trim();
    if (!text || sending) return;
    setSending(true);
    setError(null);
    try {
      const res = await nativeMutationFetch(
        `/api/affiliates/admin/messages/${message.id}/reply`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          credentials: "include",
          body: JSON.stringify({
            reply: text,
            attachments: attachments.map((a) => ({
              filename: a.filename,
              contentType: a.contentType,
              content: a.content,
            })),
          }),
        }
      );
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data?.ok === false) {
        setError(data?.error?.message || data?.error || "Could not send reply.");
        return;
      }
      setSent(true);
      onReplied();
    } catch {
      setError("Could not send reply. Please try again.");
    } finally {
      setSending(false);
    }
  }, [reply, sending, message.id, onReplied, attachments]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div
        className="absolute inset-0 bg-[#20282c]/50 backdrop-blur-sm"
        onClick={onClose}
      />
      <div className="relative glass-surface-strong rounded-lg p-7 md:p-9 max-w-lg w-full max-h-[90vh] overflow-y-auto">
        <button
          onClick={onClose}
          className="absolute top-4 right-4 p-2 rounded-full hover:bg-[#242526]/5"
          aria-label="Close"
        >
          <X className="h-4 w-4" />
        </button>

        <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] mb-1">
          {formatShortDate(message.createdAt)}
        </p>
        <h3 className="text-2xl font-medium tracking-tight">{message.name}</h3>
        <a
          href={`mailto:${message.email}`}
          className="text-sm text-[#64717a] hover:underline mt-0.5 inline-block"
        >
          {message.email}
        </a>

        <div className="mt-4">
          <Pill tone="neutral">{subjectLabel(message.subject)}</Pill>
        </div>

        <div className="mt-5 rounded-lg bg-[#242526]/4 border border-[#242526]/8 p-5">
          <p className="text-sm leading-relaxed text-[#20282c] whitespace-pre-wrap">
            {message.message}
          </p>
        </div>

        {composing && !sent && (
          <div className="mt-5">
            <label className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] mb-2 block">
              Reply to {message.name.split(/\s+/)[0] || message.email}
            </label>
            <textarea
              autoFocus
              value={reply}
              onChange={(e) => setReply(e.target.value)}
              onKeyDown={(e) => {
                if ((e.metaKey || e.ctrlKey) && e.key === "Enter") sendReply();
              }}
              rows={5}
              maxLength={10000}
              placeholder="Type your reply… it will be emailed to the customer."
              className="w-full rounded-lg border border-[#242526]/12 bg-white/70 p-4 text-sm leading-relaxed text-[#20282c] outline-none focus:border-[#242526]/40 resize-y"
            />
            <div className="mt-1.5 flex items-center justify-between gap-3">
              <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
                Sends from your IQON support email · ⌘/Ctrl + Enter
              </p>
              <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                disabled={sending || attachments.length >= MAX_REPLY_ATTACHMENTS}
                className="inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 text-[10px] uppercase tracking-[0.16em] font-sans text-[#64717a] hover:text-[#20282c] hover:bg-[#242526]/5 transition-colors disabled:opacity-40 disabled:cursor-not-allowed shrink-0"
              >
                <Paperclip className="h-3.5 w-3.5" />
                Attach
              </button>
              <input
                ref={fileInputRef}
                type="file"
                multiple
                className="hidden"
                onChange={(e) => addFiles(e.target.files)}
              />
            </div>

            {attachments.length > 0 && (
              <ul className="mt-3 space-y-2">
                {attachments.map((a, i) => (
                  <li
                    key={`${a.filename}-${i}`}
                    className="flex items-center gap-3 rounded-lg border border-[#242526]/10 bg-white/70 px-3 py-2"
                  >
                    {a.previewUrl ? (
                      // eslint-disable-next-line @next/next/no-img-element
                      <img
                        src={a.previewUrl}
                        alt={a.filename}
                        className="h-10 w-10 rounded-lg object-cover shrink-0"
                      />
                    ) : (
                      <span className="h-10 w-10 rounded-lg bg-[#242526]/6 flex items-center justify-center shrink-0">
                        <FileText className="h-4 w-4 text-[#64717a]" />
                      </span>
                    )}
                    <span className="min-w-0 flex-1">
                      <span className="block text-sm text-[#20282c] truncate">
                        {a.filename}
                      </span>
                      <span className="block text-[10px] font-sans text-[#64717a]">
                        {formatFileSize(a.size)}
                      </span>
                    </span>
                    <button
                      type="button"
                      onClick={() => removeAttachment(i)}
                      disabled={sending}
                      className="p-1.5 rounded-full text-[#64717a] hover:text-red-600 hover:bg-red-50 transition-colors shrink-0"
                      aria-label={`Remove ${a.filename}`}
                    >
                      <X className="h-3.5 w-3.5" />
                    </button>
                  </li>
                ))}
              </ul>
            )}

            {error && (
              <p className="mt-2 text-sm text-red-600">{error}</p>
            )}
          </div>
        )}

        {sent && (
          <div className="mt-5 flex items-center gap-2 rounded-lg bg-emerald-500/10 border border-emerald-600/20 p-4 text-sm text-emerald-700">
            <Check className="h-4 w-4 shrink-0" />
            Reply sent to {message.email}.
          </div>
        )}

        <div className="mt-7 flex flex-wrap gap-3">
          {sent ? null : composing ? (
            <>
              <button
                onClick={sendReply}
                disabled={sending || !reply.trim()}
                className="flex-1 min-w-[140px] inline-flex items-center justify-center gap-2 rounded-full py-3 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526] text-white hover:bg-[#20282c] transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
              >
                {sending ? (
                  <>
                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
                    Sending…
                  </>
                ) : (
                  <>
                    <Send className="h-3.5 w-3.5" />
                    Send reply
                  </>
                )}
              </button>
              <button
                onClick={() => {
                  setComposing(false);
                  setError(null);
                  setAttachments((prev) => {
                    prev.forEach((a) => a.previewUrl && URL.revokeObjectURL(a.previewUrl));
                    return [];
                  });
                }}
                disabled={sending}
                className="inline-flex items-center justify-center gap-2 rounded-full px-5 py-3 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526]/5 text-[#20282c] hover:bg-[#242526]/10 transition-colors disabled:opacity-40"
              >
                Cancel
              </button>
            </>
          ) : (
            <button
              onClick={() => setComposing(true)}
              className="flex-1 min-w-[140px] inline-flex items-center justify-center gap-2 rounded-full py-3 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526] text-white hover:bg-[#20282c] transition-colors"
            >
              <Reply className="h-3.5 w-3.5" />
              Reply
            </button>
          )}

          {!composing && !sent && (
            <>
              <button
                onClick={onArchive}
                className="inline-flex items-center justify-center gap-2 rounded-full px-5 py-3 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526]/5 text-[#20282c] hover:bg-[#242526]/10 transition-colors"
              >
                {message.status === "archived" ? (
                  <>
                    <RotateCcw className="h-3.5 w-3.5" />
                    Restore
                  </>
                ) : (
                  <>
                    <Archive className="h-3.5 w-3.5" />
                    Archive
                  </>
                )}
              </button>
              <button
                onClick={onDelete}
                className="inline-flex items-center justify-center gap-2 rounded-full px-5 py-3 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#64717a]/10 text-[#64717a] hover:bg-[#64717a]/15 transition-colors"
              >
                <Trash2 className="h-3.5 w-3.5" />
                Delete
              </button>
            </>
          )}

          {sent && (
            <button
              onClick={onClose}
              className="flex-1 min-w-[140px] inline-flex items-center justify-center gap-2 rounded-full py-3 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526]/5 text-[#20282c] hover:bg-[#242526]/10 transition-colors"
            >
              Done
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";
import {nonproviderMutationFetch} from "@/lib/affiliates/nonprovider-mutation-fetch";

import { useCallback, useEffect, useMemo, useState } from "react";
import {
  StickyNote,
  Plus,
  Pin,
  PinOff,
  Pencil,
  Trash2,
  Check,
  X,
  Search,
  Loader2,
  Tag,
} from "lucide-react";
import {
  PageHeader,
  Pill,
  EmptyState,
  formatShortDate,
} from "@/components/affiliates/shared/ui";

interface AdminNote {
  id: string;
  title: string | null;
  body: string;
  tag: string | null;
  pinned: boolean;
  authorEmail: string;
  authorName: string | null;
  createdAt: string;
  updatedAt: string;
}

export default function AdminNotesPage() {
  const [notes, setNotes] = useState<AdminNote[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");

  // Composer
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [tag, setTag] = useState("");
  const [pinned, setPinned] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Inline edit
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState("");
  const [editBody, setEditBody] = useState("");
  const [editTag, setEditTag] = useState("");

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/affiliates/admin/notes", {
        credentials: "include",
      });
      if (res.ok) {
        const data = await res.json();
        setNotes(data.notes ?? []);
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const sortNotes = (list: AdminNote[]) =>
    [...list].sort((a, b) => {
      if (a.pinned !== b.pinned) return a.pinned ? -1 : 1;
      return b.updatedAt.localeCompare(a.updatedAt);
    });

  const addNote = useCallback(async () => {
    const text = body.trim();
    if (!text || saving) return;
    setSaving(true);
    setError(null);
    try {
      const res = await fetch("/api/affiliates/admin/notes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          title: title.trim() || undefined,
          body: text,
          tag: tag.trim() || undefined,
          pinned,
        }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data?.ok === false) {
        setError(data?.error?.message || data?.error || "Could not save note.");
        return;
      }
      if (data.note) setNotes((prev) => sortNotes([data.note, ...prev]));
      setTitle("");
      setBody("");
      setTag("");
      setPinned(false);
    } catch {
      setError("Could not save note. Please try again.");
    } finally {
      setSaving(false);
    }
  }, [title, body, tag, pinned, saving]);

  const togglePin = useCallback(async (note: AdminNote) => {
    const next = !note.pinned;
    setNotes((prev) =>
      sortNotes(prev.map((n) => (n.id === note.id ? { ...n, pinned: next } : n)))
    );
    await fetch(`/api/affiliates/admin/notes/${note.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
      body: JSON.stringify({ pinned: next }),
    }).catch(() => {});
  }, []);

  const removeNote = useCallback(async (id: string) => {
    if (!window.confirm("Delete this note permanently?")) return;
    try {
      const response = await nonproviderMutationFetch(`/api/affiliates/admin/notes/${id}`, {
        method: "DELETE",
        credentials: "include",
      });
      if (!response.ok) return;
      setNotes((prev) => prev.filter((n) => n.id !== id));
      if (editingId === id) setEditingId(null);
    } catch {
      // Keep the original control and operation UUID for an uncertain retry.
    }
  }, [editingId]);

  function startEdit(note: AdminNote) {
    setEditingId(note.id);
    setEditTitle(note.title ?? "");
    setEditBody(note.body);
    setEditTag(note.tag ?? "");
  }

  const saveEdit = useCallback(async () => {
    if (!editingId) return;
    const text = editBody.trim();
    if (!text) return;
    const id = editingId;
    const patch = {
      title: editTitle.trim() || null,
      body: text,
      tag: editTag.trim() || null,
    };
    setNotes((prev) =>
      sortNotes(
        prev.map((n) =>
          n.id === id
            ? { ...n, ...patch, updatedAt: new Date().toISOString() }
            : n
        )
      )
    );
    setEditingId(null);
    await fetch(`/api/affiliates/admin/notes/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
      body: JSON.stringify(patch),
    }).catch(() => {});
  }, [editingId, editTitle, editBody, editTag]);

  const visible = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return notes;
    return notes.filter((n) =>
      [n.title, n.body, n.tag, n.authorName, n.authorEmail]
        .filter(Boolean)
        .some((v) => (v as string).toLowerCase().includes(q))
    );
  }, [notes, search]);

  return (
    <>
      <PageHeader
        eyebrow="Workspace"
        title="Notes"
        description="Internal notes for the team — track anything about orders, customers, or operations. Only admins can see these."
        actions={
          <span className="inline-flex items-center gap-2 glass-surface rounded-full px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
            <StickyNote className="h-3.5 w-3.5" />
            {notes.length} {notes.length === 1 ? "note" : "notes"}
          </span>
        }
      />

      {/* Composer */}
      <div className="glass-surface rounded-lg p-5 sm:p-6 mb-6">
        <input
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          maxLength={200}
          placeholder="Title (optional)"
          className="w-full bg-transparent text-lg font-medium text-[#20282c] placeholder:text-[#64717a]/60 outline-none mb-2"
        />
        <textarea
          value={body}
          onChange={(e) => setBody(e.target.value)}
          onKeyDown={(e) => {
            if ((e.metaKey || e.ctrlKey) && e.key === "Enter") addNote();
          }}
          rows={3}
          maxLength={10000}
          placeholder="Write a note… e.g. “Order #665 — customer asked to delay shipping until Friday.”"
          className="w-full rounded-lg border border-[#242526]/12 bg-white/70 p-4 text-sm leading-relaxed text-[#20282c] outline-none focus:border-[#242526]/40 resize-y"
        />
        <div className="mt-3 flex flex-wrap items-center gap-3">
          <div className="inline-flex items-center gap-2 rounded-full bg-white/70 border border-[#242526]/12 px-3 py-2">
            <Tag className="h-3.5 w-3.5 text-[#64717a]" />
            <input
              value={tag}
              onChange={(e) => setTag(e.target.value)}
              maxLength={120}
              placeholder="Related to (e.g. Order #665)"
              className="bg-transparent text-sm text-[#20282c] placeholder:text-[#64717a]/60 outline-none w-52 max-w-[60vw]"
            />
          </div>
          <button
            onClick={() => setPinned((p) => !p)}
            className={`inline-flex items-center gap-2 rounded-full px-3 py-2 text-[10px] uppercase tracking-[0.18em] font-sans transition-colors ${
              pinned
                ? "bg-[#242526] text-white"
                : "bg-[#242526]/5 text-[#64717a] hover:text-[#20282c]"
            }`}
          >
            <Pin className="h-3.5 w-3.5" />
            {pinned ? "Pinned" : "Pin"}
          </button>
          <div className="flex-1" />
          <button
            onClick={addNote}
            disabled={saving || !body.trim()}
            className="inline-flex items-center justify-center gap-2 rounded-full px-5 py-2.5 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526] text-white hover:bg-[#20282c] transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
          >
            {saving ? (
              <>
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
                Saving…
              </>
            ) : (
              <>
                <Plus className="h-3.5 w-3.5" />
                Add note
              </>
            )}
          </button>
        </div>
        {error && <p className="mt-2 text-sm text-red-600">{error}</p>}
      </div>

      {/* Search */}
      {notes.length > 0 && (
        <div className="mb-5 inline-flex items-center gap-2 glass-surface rounded-full px-4 py-2 w-full sm:w-auto">
          <Search className="h-3.5 w-3.5 text-[#64717a]" />
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search notes…"
            className="bg-transparent text-sm text-[#20282c] placeholder:text-[#64717a]/60 outline-none w-full sm:w-64"
          />
          {search && (
            <button
              onClick={() => setSearch("")}
              className="p-1 rounded-full hover:bg-[#242526]/5"
              aria-label="Clear search"
            >
              <X className="h-3.5 w-3.5 text-[#64717a]" />
            </button>
          )}
        </div>
      )}

      {loading ? (
        <div className="glass-surface rounded-lg p-12 text-center text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
          Loading…
        </div>
      ) : visible.length === 0 ? (
        <EmptyState
          icon={StickyNote}
          title={notes.length === 0 ? "No notes yet" : "No matches"}
          description={
            notes.length === 0
              ? "Add your first note above — anything the team should remember about orders or customers."
              : "No notes match your search."
          }
        />
      ) : (
        <ul className="grid gap-3 sm:grid-cols-2">
          {visible.map((note) => {
            const editing = editingId === note.id;
            return (
              <li
                key={note.id}
                className="glass-surface rounded-lg p-5 sm:p-6 flex flex-col"
              >
                {editing ? (
                  <>
                    <input
                      value={editTitle}
                      onChange={(e) => setEditTitle(e.target.value)}
                      maxLength={200}
                      placeholder="Title (optional)"
                      className="w-full bg-transparent text-base font-medium text-[#20282c] placeholder:text-[#64717a]/60 outline-none mb-2"
                    />
                    <textarea
                      value={editBody}
                      onChange={(e) => setEditBody(e.target.value)}
                      onKeyDown={(e) => {
                        if ((e.metaKey || e.ctrlKey) && e.key === "Enter") saveEdit();
                        if (e.key === "Escape") setEditingId(null);
                      }}
                      rows={4}
                      maxLength={10000}
                      className="w-full rounded-lg border border-[#242526]/12 bg-white/70 p-3 text-sm leading-relaxed text-[#20282c] outline-none focus:border-[#242526]/40 resize-y"
                    />
                    <div className="mt-2 inline-flex items-center gap-2 rounded-full bg-white/70 border border-[#242526]/12 px-3 py-1.5 w-fit">
                      <Tag className="h-3.5 w-3.5 text-[#64717a]" />
                      <input
                        value={editTag}
                        onChange={(e) => setEditTag(e.target.value)}
                        maxLength={120}
                        placeholder="Related to"
                        className="bg-transparent text-sm text-[#20282c] placeholder:text-[#64717a]/60 outline-none w-40"
                      />
                    </div>
                    <div className="mt-4 flex gap-2">
                      <button
                        onClick={saveEdit}
                        disabled={!editBody.trim()}
                        className="inline-flex items-center gap-2 rounded-full px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526] text-white hover:bg-[#20282c] transition-colors disabled:opacity-40"
                      >
                        <Check className="h-3.5 w-3.5" />
                        Save
                      </button>
                      <button
                        onClick={() => setEditingId(null)}
                        className="inline-flex items-center gap-2 rounded-full px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526]/5 text-[#20282c] hover:bg-[#242526]/10 transition-colors"
                      >
                        Cancel
                      </button>
                    </div>
                  </>
                ) : (
                  <>
                    <div className="flex items-start justify-between gap-3">
                      <div className="min-w-0 flex-1">
                        {note.title && (
                          <h3 className="font-semibold text-[#20282c] truncate">
                            {note.title}
                          </h3>
                        )}
                        {note.tag && (
                          <div className="mt-1">
                            <Pill tone="neutral">{note.tag}</Pill>
                          </div>
                        )}
                      </div>
                      {note.pinned && (
                        <Pin className="h-3.5 w-3.5 text-[#242526] shrink-0 mt-1" />
                      )}
                    </div>
                    <p className="text-sm leading-relaxed text-[#20282c]/90 whitespace-pre-wrap mt-3 flex-1">
                      {note.body}
                    </p>
                    <div className="mt-4 pt-3 border-t border-[#242526]/8 flex items-center justify-between gap-3">
                      <p className="text-[10px] uppercase tracking-[0.14em] font-sans text-[#64717a] truncate">
                        {note.authorName || note.authorEmail} ·{" "}
                        {formatShortDate(note.updatedAt)}
                      </p>
                      <div className="flex items-center gap-1 shrink-0">
                        <button
                          onClick={() => togglePin(note)}
                          className="p-2 rounded-full hover:bg-[#242526]/5"
                          title={note.pinned ? "Unpin" : "Pin"}
                        >
                          {note.pinned ? (
                            <PinOff className="h-3.5 w-3.5 text-[#64717a]" />
                          ) : (
                            <Pin className="h-3.5 w-3.5 text-[#64717a]" />
                          )}
                        </button>
                        <button
                          onClick={() => startEdit(note)}
                          className="p-2 rounded-full hover:bg-[#242526]/5"
                          title="Edit"
                        >
                          <Pencil className="h-3.5 w-3.5 text-[#64717a]" />
                        </button>
                        <button
                          onClick={() => removeNote(note.id)}
                          className="p-2 rounded-full hover:bg-[#242526]/5"
                          title="Delete"
                        >
                          <Trash2 className="h-3.5 w-3.5 text-[#64717a]" />
                        </button>
                      </div>
                    </div>
                  </>
                )}
              </li>
            );
          })}
        </ul>
      )}
    </>
  );
}

"use client";
import {ShopifyOrders} from "@/components/affiliates/ShopifyOrders";
import {providerMutationFetch} from '@/lib/affiliates/provider-mutation-fetch';
import { useLatestRead } from "@/lib/affiliates/use-latest-read";

import { Suspense, useCallback, useEffect, useMemo, useState } from "react";
import { useSearchParams } from "next/navigation";
import {
  Search,
  ShoppingBag,
  ChevronDown,
  Tag,
  Repeat,
  Loader2,
  UserPlus,
  Lock,
  Sparkles,
  Undo2,
  PackageCheck,
} from "lucide-react";
import { toast } from "sonner";
import { RangePicker, type Preset } from "@/components/affiliates/shared/RangePicker";
import { isMonthToken, isPresetRange } from "@/lib/affiliates/time-series";
import {
  PageHeader,
  Pill,
  EmptyState,
  formatCurrency,
  formatShortDate,
} from "@/components/affiliates/shared/ui";

interface OrderItem {
  name: string;
  quantity: number;
  total: string;
}

interface OrderAffiliate {
  affiliateId: string;
  name: string;
  promoCode: string;
  commission: number;
  matchType: string;
  locked: boolean;
}

interface AffiliateOption {
  id: string;
  name: string;
  promoCode: string;
}

interface AdminOrder {
  id: number;
  status: string;
  date: string;
  total: string;
  currency: string;
  customerName: string;
  customerEmail: string;
  items: OrderItem[];
  couponCodes: string[];
  customerType: "new" | "recurring";
  /** True when a refunded order's products were also returned (restocked). */
  returned: boolean;
  affiliate: OrderAffiliate | null;
}

function toNum(v: string | number | null | undefined): number {
  const n = parseFloat(String(v ?? "0").replace(/[^0-9.-]/g, ""));
  return Number.isFinite(n) ? n : 0;
}

// "paid" (the default) = processing + completed, matching what this page
// showed before unpaid statuses were added.
type StatusFilter =
  | "paid"
  | "completed"
  | "processing"
  | "pending"
  | "on-hold"
  | "refunded";

const STATUS_FILTERS: { id: StatusFilter; label: string }[] = [
  { id: "paid", label: "Paid" },
  { id: "completed", label: "Completed" },
  { id: "processing", label: "Processing" },
  { id: "pending", label: "Pending payment" },
  { id: "on-hold", label: "On hold" },
  { id: "refunded", label: "Refunded" },
];

function matchesStatus(orderStatus: string, filter: StatusFilter): boolean {
  if (filter === "paid") {
    return orderStatus === "processing" || orderStatus === "completed";
  }
  return orderStatus === filter;
}

export default function AdminOrdersPage() {
  return (
    <Suspense fallback={null}>
      <AdminOrdersPageInner />
    </Suspense>
  );
}

function AdminOrdersPageInner() {
  // Deep links from the overview (revenue number → orders of that range)
  // carry the selected range as ?range=…
  const searchParams = useSearchParams();
  const rangeParam = searchParams.get("range");
  const initialPreset: Preset =
    isPresetRange(rangeParam) || isMonthToken(rangeParam) ? rangeParam : "30d";

  const [source,setSource]=useState<"peptides"|"shopify">(searchParams.get("source")==="shopify"?"shopify":"peptides");
  const [orders, setOrders] = useState<AdminOrder[]>([]);
  const [affiliateOptions, setAffiliateOptions] = useState<AffiliateOption[]>([]);
  const [truncated, setTruncated] = useState(false);
  const [loading, setLoading] = useState(true);
  const [preset, setPreset] = useState<Preset>(initialPreset);
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState<
    "all" | "affiliate" | "direct" | "new" | "recurring"
  >("all");
  const [statusFilter, setStatusFilter] = useState<StatusFilter>("paid");
  const [expanded, setExpanded] = useState<Set<number>>(new Set());
  // Per-order attribution UI state: chosen affiliate in the picker + saving flag.
  const [attrChoice, setAttrChoice] = useState<Record<number, string>>({});
  const [attrSaving, setAttrSaving] = useState<Set<number>>(new Set());

  const beginRead = useLatestRead();
  const [readError, setReadError] = useState<string | null>(null);
  const load = useCallback(async (p: Preset) => {
    setLoading(true);
    const request = beginRead();
    setReadError(null);
    setOrders([]); setTruncated(false);
    try {
      const res = await fetch(`/api/affiliates/admin/orders?range=${encodeURIComponent(p)}`, {
        credentials: "include", cache: "no-store", signal: request.signal,
      });
      if (!res.ok) throw new Error("Could not load data. Please retry.");
      if (res.ok) {
        const data = await res.json();
        if (!request.isCurrent()) return;
        setOrders(data.orders ?? []);
        setAffiliateOptions(data.affiliates ?? []);
        setTruncated(Boolean(data.truncated));
      }
    } catch {
      if (request.isCurrent()) setReadError("Could not load data. Please retry.");
    } finally {
      if (!request.isCurrent()) return;
      setLoading(false);
    }
  }, [beginRead]);

  useEffect(() => {
    load(preset);
  }, [preset, load]);

  const toggle = (id: number) =>
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });

  const setSaving = (id: number, on: boolean) =>
    setAttrSaving((prev) => {
      const next = new Set(prev);
      if (on) next.add(id);
      else next.delete(id);
      return next;
    });

  const attributeOrder = useCallback(
    async (orderId: number, affiliateId: string) => {
      if (!affiliateId) {
        toast.error("Pick an affiliate first.");
        return;
      }
      setSaving(orderId, true);
      try {
        const res = await providerMutationFetch(
          `/api/affiliates/admin/orders/${orderId}/attribute`,
          {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            credentials: "include",
            body: JSON.stringify({ affiliateId }),
          }
        );
        const data = await res.json().catch(() => ({}));
        if (!res.ok) {
          toast.error(data.error ?? "Could not attribute this order.");
          return;
        }
        const attr = data.attribution ?? {};
        const commissionText =
          typeof attr.commission === "number"
            ? ` · ${formatCurrency(attr.commission)} commission`
            : "";
        toast.success(
          `${attr.reassigned ? "Reassigned" : "Attributed"} to ${attr.affiliateName ?? "affiliate"}${commissionText}${
            attr.referralCredited ? " (network commission credited too)" : ""
          }`
        );
        await load(preset);
      } finally {
        setSaving(orderId, false);
      }
    },
    [load, preset]
  );

  const removeAttribution = useCallback(
    async (orderId: number) => {
      if (
        !window.confirm(
          "Remove this order's affiliate attribution? The pending commission will be deleted."
        )
      )
        return;
      setSaving(orderId, true);
      try {
        const res = await providerMutationFetch(
          `/api/affiliates/admin/orders/${orderId}/attribute`,
          { method: "DELETE", credentials: "include" }
        );
        const data = await res.json().catch(() => ({}));
        if (!res.ok) {
          toast.error(data.error ?? "Could not remove attribution.");
          return;
        }
        toast.success("Attribution removed.");
        await load(preset);
      } finally {
        setSaving(orderId, false);
      }
    },
    [load, preset]
  );

  const markRefund = useCallback(
    async (orderId: number, action: "refund" | "return") => {
      const confirmText =
        action === "return"
          ? `Mark order #${orderId} as refunded AND returned?\n\nIt will be removed from revenue, any pending commission is voided, and the units go back into inventory.`
          : `Mark order #${orderId} as refunded (customer keeps the products)?\n\nIt will be removed from revenue and any pending commission is voided. Stock stays deducted — use "returned" if the products came back.`;
      if (!window.confirm(confirmText)) return;
      setSaving(orderId, true);
      try {
        const res = await providerMutationFetch(`/api/affiliates/admin/orders/${orderId}/refund`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          credentials: "include",
          body: JSON.stringify({ action }),
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) {
          toast.error(data.error ?? "Could not update this order.");
          return;
        }
        toast.success(
          action === "return"
            ? `Order #${orderId} marked returned — stock is back in inventory.`
            : `Order #${orderId} marked refunded.`
        );
        await load(preset);
      } finally {
        setSaving(orderId, false);
      }
    },
    [load, preset]
  );

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    return orders.filter((o) => {
      if (!matchesStatus(o.status, statusFilter)) return false;
      if (filter === "affiliate" && !o.affiliate) return false;
      if (filter === "direct" && o.affiliate) return false;
      if (filter === "new" && o.customerType !== "new") return false;
      if (filter === "recurring" && o.customerType !== "recurring") return false;
      if (!q) return true;
      return (
        o.customerName.toLowerCase().includes(q) ||
        o.customerEmail.toLowerCase().includes(q) ||
        String(o.id).includes(q) ||
        (o.affiliate?.promoCode.toLowerCase().includes(q) ?? false) ||
        (o.affiliate?.name.toLowerCase().includes(q) ?? false) ||
        o.items.some((it) => it.name.toLowerCase().includes(q))
      );
    });
  }, [orders, search, filter, statusFilter]);

  const totals = useMemo(() => {
    const revenue = filtered.reduce((s, o) => s + toNum(o.total), 0);
    const fromAffiliates = filtered
      .filter((o) => o.affiliate)
      .reduce((s, o) => s + toNum(o.total), 0);
    return { revenue, fromAffiliates, count: filtered.length };
  }, [filtered]);

  const sourcePicker=<div className="flex flex-wrap gap-2 mb-6" aria-label="Order source">{([['peptides','Peptides · WooCommerce'],['shopify','Supplements · Shopify']] as const).map(([id,label])=><button key={id} aria-pressed={source===id} onClick={()=>setSource(id)} className={`rounded-full border px-4 py-2 text-xs ${source===id?'bg-[#12201C] text-white':'bg-white/50'}`}>{label}</button>)}</div>;
  if(source==='shopify')return <><PageHeader eyebrow="Orders" title="Shopify orders" description="IQON Daily store orders, separate from peptide sales and affiliate commissions." actions={<RangePicker value={preset} onChange={setPreset}/>}/>{sourcePicker}<ShopifyOrders preset={preset}/></>;
  return (
    <>
      {readError && <p role="alert">{readError} <button type="button" onClick={() => load(preset)}>Retry</button></p>}
      <PageHeader
        eyebrow="Orders"
        title="All orders"
        description="Every order with products, totals, and the affiliate (if any) attributed to it. Defaults to paid orders (processing + completed); use the status filter for pending payment, on hold, or refunded. Open an order to flag it refunded or returned."
        actions={<RangePicker value={preset} onChange={setPreset} />}
      />

      {sourcePicker}
      {/* Summary line */}
      <section className="grid grid-cols-1 sm:grid-cols-3 gap-3 md:gap-4 mb-6">
        <div className="glass-surface rounded-lg p-5">
          <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
            Orders
          </p>
          <p className="text-2xl font-medium font-sans tracking-tight mt-2">
            {totals.count}
          </p>
        </div>
        <div className="glass-surface rounded-lg p-5">
          <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
            Revenue
          </p>
          <p className="text-2xl font-medium font-sans tracking-tight mt-2">
            {formatCurrency(totals.revenue)}
          </p>
        </div>
        <div className="glass-surface rounded-lg p-5">
          <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
            From affiliates
          </p>
          <p className="text-2xl font-medium font-sans tracking-tight mt-2">
            {formatCurrency(totals.fromAffiliates)}
          </p>
        </div>
      </section>

      <section className="flex flex-col gap-3 mb-6">
        <div className="flex flex-col sm:flex-row gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-[#64717a]" />
            <input
              type="text"
              placeholder="Search by customer, product, order #, or affiliate code"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full glass-surface rounded-full pl-9 pr-4 py-2.5 text-sm placeholder:text-[#64717a] focus:outline-none focus:ring-2 focus:ring-[#242526]/15"
            />
          </div>
          <div className="inline-flex items-center glass-surface rounded-full p-1 gap-1 overflow-x-auto">
            {(["all", "affiliate", "direct", "new", "recurring"] as const).map((f) => (
              <button
                key={f}
                onClick={() => setFilter(f)}
                className={`px-3 py-1.5 rounded-full text-[10px] uppercase tracking-[0.18em] font-sans transition-colors whitespace-nowrap ${
                  filter === f
                    ? "bg-[#242526] text-white"
                    : "text-[#64717a] hover:text-[#20282c]"
                }`}
              >
                {f}
              </button>
            ))}
          </div>
        </div>
        <div className="inline-flex items-center self-start glass-surface rounded-full p-1 gap-1 overflow-x-auto max-w-full">
          {STATUS_FILTERS.map((s) => (
            <button
              key={s.id}
              onClick={() => setStatusFilter(s.id)}
              className={`px-3 py-1.5 rounded-full text-[10px] uppercase tracking-[0.18em] font-sans transition-colors whitespace-nowrap ${
                statusFilter === s.id
                  ? "bg-[#242526] text-white"
                  : "text-[#64717a] hover:text-[#20282c]"
              }`}
            >
              {s.label}
            </button>
          ))}
        </div>
      </section>

      {truncated && (
        <div className="mb-4 glass-surface rounded-lg px-5 py-3 text-xs text-[#64717a]">
          Showing the most recent orders for this range; older orders were
          truncated. Narrow the date range to see the rest.
        </div>
      )}

      {loading ? (
        <div className="glass-surface rounded-lg p-12 text-center text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
          Loading…
        </div>
      ) : filtered.length === 0 ? (
        <EmptyState
          icon={ShoppingBag}
          title={
            search || filter !== "all" || statusFilter !== "paid"
              ? "No matches"
              : "No paid orders yet"
          }
          description={
            search || filter !== "all" || statusFilter !== "paid"
              ? "Try a different filter or search term."
              : "Paid orders (processing or completed) will appear here."
          }
        />
      ) : (
        <div className="glass-surface rounded-lg overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full min-w-[920px] text-sm">
              <thead>
                <tr className="border-b border-[#242526]/8">
                  <Th>Date</Th>
                  <Th>Customer</Th>
                  <Th>Type</Th>
                  <Th>Items</Th>
                  <Th>Affiliate</Th>
                  <Th align="right">Total</Th>
                  <Th>Status</Th>
                  <Th />
                </tr>
              </thead>
              <tbody>
                {filtered.map((o) => {
                  const isOpen = expanded.has(o.id);
                  const itemCount = o.items.reduce((s, it) => s + it.quantity, 0);
                  const summary = o.items
                    .map((it) => `${it.name}${it.quantity > 1 ? ` ×${it.quantity}` : ""}`)
                    .join(", ");
                  return (
                    <FragmentRow key={o.id}>
                      <tr
                        onClick={() => toggle(o.id)}
                        className="border-b border-[#242526]/5 cursor-pointer hover:bg-[#242526]/[0.03] transition-colors"
                      >
                        <td className="py-4 px-5 font-sans text-xs text-[#64717a] whitespace-nowrap">
                          {formatShortDate(o.date)}
                        </td>
                        <td className="py-4 px-5">
                          <p className="font-medium leading-tight">{o.customerName || "—"}</p>
                          <p className="text-xs text-[#64717a] mt-0.5">{o.customerEmail}</p>
                        </td>
                        <td className="py-4 px-5">
                          {o.customerType === "recurring" ? (
                            <Pill tone="neutral" icon={Repeat}>
                              Recurring
                            </Pill>
                          ) : (
                            <Pill tone="success" icon={Sparkles}>
                              New
                            </Pill>
                          )}
                        </td>
                        <td className="py-4 px-5 max-w-[18rem]">
                          <p className="truncate text-[#20282c]">{summary || "—"}</p>
                          <p className="text-xs text-[#64717a] mt-0.5">
                            {itemCount} {itemCount === 1 ? "item" : "items"} · #{o.id}
                          </p>
                        </td>
                        <td className="py-4 px-5">
                          {o.affiliate ? (
                            <Pill
                              tone="dark"
                              icon={o.affiliate.matchType === "recurring" ? Repeat : Tag}
                            >
                              {o.affiliate.promoCode || o.affiliate.name}
                            </Pill>
                          ) : (
                            <span className="text-xs text-[#64717a]">—</span>
                          )}
                        </td>
                        <td className="py-4 px-5 text-right font-sans">
                          {formatCurrency(toNum(o.total), o.currency)}
                        </td>
                        <td className="py-4 px-5">
                          <Pill
                            tone={
                              o.status === "refunded"
                                ? "danger"
                                : o.status === "completed"
                                  ? "success"
                                  : o.status === "processing"
                                    ? "neutral"
                                    : "warn"
                            }
                          >
                            {o.status === "pending"
                              ? "pending payment"
                              : o.status === "refunded" && o.returned
                                ? "refunded · returned"
                                : o.status.replace(/-/g, " ")}
                          </Pill>
                        </td>
                        <td className="py-4 px-3 text-right">
                          <ChevronDown
                            className={`h-4 w-4 text-[#64717a] inline-block transition-transform ${
                              isOpen ? "rotate-180" : ""
                            }`}
                          />
                        </td>
                      </tr>
                      {isOpen && (
                        <tr className="border-b border-[#242526]/5 bg-[#242526]/[0.02]">
                          <td colSpan={8} className="px-5 py-5">
                            <div className="grid grid-cols-1 lg:grid-cols-[1.6fr_1fr] gap-6">
                              <div>
                                <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] mb-3">
                                  Products
                                </p>
                                <ul className="space-y-2">
                                  {o.items.map((it, idx) => (
                                    <li
                                      key={idx}
                                      className="flex items-center justify-between gap-4 text-sm"
                                    >
                                      <span className="text-[#20282c]">
                                        {it.name}
                                        <span className="text-[#64717a]">
                                          {" "}
                                          × {it.quantity}
                                        </span>
                                      </span>
                                      <span className="font-sans text-[#20282c]">
                                        {formatCurrency(toNum(it.total), o.currency)}
                                      </span>
                                    </li>
                                  ))}
                                </ul>
                              </div>
                              <div className="space-y-3 text-sm">
                                <DetailRow label="Order total">
                                  <span className="font-sans">
                                    {formatCurrency(toNum(o.total), o.currency)}
                                  </span>
                                </DetailRow>
                                <DetailRow label="Coupons">
                                  {o.couponCodes.length > 0 ? (
                                    <span className="font-sans text-xs">
                                      {o.couponCodes.join(", ")}
                                    </span>
                                  ) : (
                                    <span className="text-[#64717a]">None</span>
                                  )}
                                </DetailRow>
                                <DetailRow label="Affiliate">
                                  {o.affiliate ? (
                                    <span>
                                      {o.affiliate.name}
                                      {o.affiliate.promoCode
                                        ? ` (${o.affiliate.promoCode})`
                                        : ""}
                                    </span>
                                  ) : (
                                    <span className="text-[#64717a]">None</span>
                                  )}
                                </DetailRow>
                                {o.affiliate && (
                                  <DetailRow label="Commission">
                                    <span className="font-sans">
                                      {formatCurrency(o.affiliate.commission, o.currency)}
                                    </span>
                                  </DetailRow>
                                )}
                                <AttributionControl
                                  order={o}
                                  affiliates={affiliateOptions}
                                  value={attrChoice[o.id] ?? o.affiliate?.affiliateId ?? ""}
                                  saving={attrSaving.has(o.id)}
                                  onChange={(v) =>
                                    setAttrChoice((prev) => ({ ...prev, [o.id]: v }))
                                  }
                                  onAttribute={() =>
                                    attributeOrder(
                                      o.id,
                                      attrChoice[o.id] ?? o.affiliate?.affiliateId ?? ""
                                    )
                                  }
                                  onRemove={() => removeAttribution(o.id)}
                                />
                                <RefundControl
                                  order={o}
                                  saving={attrSaving.has(o.id)}
                                  onRefund={() => markRefund(o.id, "refund")}
                                  onReturn={() => markRefund(o.id, "return")}
                                />
                              </div>
                            </div>
                          </td>
                        </tr>
                      )}
                    </FragmentRow>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </>
  );
}

function FragmentRow({ children }: { children: React.ReactNode }) {
  return <>{children}</>;
}

function AttributionControl({
  order,
  affiliates,
  value,
  saving,
  onChange,
  onAttribute,
  onRemove,
}: {
  order: AdminOrder;
  affiliates: AffiliateOption[];
  value: string;
  saving: boolean;
  onChange: (v: string) => void;
  onAttribute: () => void;
  onRemove: () => void;
}) {
  const current = order.affiliate;
  const locked = Boolean(current?.locked);
  // The picker only enables the button when the selection differs from what's
  // already saved (or nothing is saved yet), so re-clicking is a no-op.
  const changed = value !== "" && value !== (current?.affiliateId ?? "");

  return (
    <div className="mt-2 pt-3 border-t border-[#242526]/10">
      <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] mb-2">
        {current ? "Change attribution" : "Attribute to affiliate"}
      </p>
      {locked ? (
        <p className="flex items-center gap-1.5 text-xs text-[#64717a]">
          <Lock className="h-3.5 w-3.5 shrink-0" />
          Commission already paid out — remove it from the payout to reassign.
        </p>
      ) : affiliates.length === 0 ? (
        <p className="text-xs text-[#64717a]">No active affiliates to attribute to.</p>
      ) : (
        <>
          <div className="flex flex-col sm:flex-row gap-2">
            <select
              value={value}
              disabled={saving}
              onChange={(e) => onChange(e.target.value)}
              className="flex-1 glass-surface rounded-full px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#242526]/15 disabled:opacity-60"
            >
              <option value="">Select an affiliate…</option>
              {affiliates.map((a) => (
                <option key={a.id} value={a.id}>
                  {a.name}
                  {a.promoCode ? ` (${a.promoCode})` : ""}
                </option>
              ))}
            </select>
            <button
              type="button"
              onClick={onAttribute}
              disabled={saving || !changed}
              className="inline-flex items-center justify-center gap-1.5 rounded-full bg-[#242526] px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans text-white transition-opacity disabled:opacity-40 hover:opacity-90 whitespace-nowrap"
            >
              {saving ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <UserPlus className="h-3.5 w-3.5" />
              )}
              {current ? "Reassign" : "Attribute"}
            </button>
          </div>
          {current && (
            <button
              type="button"
              onClick={onRemove}
              disabled={saving}
              className="mt-2 text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] hover:text-red-600 transition-colors disabled:opacity-40"
            >
              Remove attribution
            </button>
          )}
          <p className="mt-2 text-xs text-[#64717a] leading-relaxed">
            Credits the affiliate as if their code was used — first-order rate on
            the net product total (after discounts, before shipping &amp; tax).
          </p>
        </>
      )}
    </div>
  );
}

function RefundControl({
  order,
  saving,
  onRefund,
  onReturn,
}: {
  order: AdminOrder;
  saving: boolean;
  onRefund: () => void;
  onReturn: () => void;
}) {
  const isRefunded = order.status === "refunded";

  if (isRefunded && order.returned) {
    return (
      <div className="mt-2 pt-3 border-t border-[#242526]/10">
        <p className="flex items-center gap-1.5 text-xs text-[#64717a]">
          <PackageCheck className="h-3.5 w-3.5 shrink-0" />
          Refunded and returned — units are back in inventory.
        </p>
      </div>
    );
  }

  return (
    <div className="mt-2 pt-3 border-t border-[#242526]/10">
      <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] mb-2">
        {isRefunded ? "Refunded" : "Refund / return"}
      </p>
      <div className="flex flex-col sm:flex-row gap-2">
        {!isRefunded && (
          <button
            type="button"
            onClick={onRefund}
            disabled={saving}
            className="inline-flex items-center justify-center gap-1.5 rounded-full border border-red-600/25 bg-red-600/5 px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans text-red-700 transition-colors hover:bg-red-600/10 disabled:opacity-40 whitespace-nowrap"
          >
            {saving ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Undo2 className="h-3.5 w-3.5" />
            )}
            Mark refunded
          </button>
        )}
        <button
          type="button"
          onClick={onReturn}
          disabled={saving}
          className="inline-flex items-center justify-center gap-1.5 rounded-full border border-[#242526]/15 bg-[#242526]/5 px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans text-[#20282c] transition-colors hover:bg-[#242526]/10 disabled:opacity-40 whitespace-nowrap"
        >
          {saving ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <PackageCheck className="h-3.5 w-3.5" />
          )}
          {isRefunded ? "Mark returned — restock" : "Refunded + returned"}
        </button>
      </div>
      <p className="mt-2 text-xs text-[#64717a] leading-relaxed">
        {isRefunded
          ? "This order is already out of revenue. Mark it returned when the products come back to put the units into inventory."
          : "Refunded removes the order from revenue (stock stays deducted). Refunded + returned also puts the units back into inventory."}
      </p>
    </div>
  );
}

function DetailRow({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div className="flex items-center justify-between gap-4">
      <span className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
        {label}
      </span>
      <span className="text-right text-[#20282c]">{children}</span>
    </div>
  );
}

function Th({
  children,
  align = "left",
}: {
  children?: React.ReactNode;
  align?: "left" | "right";
}) {
  return (
    <th
      className={`py-3.5 px-5 font-sans text-[10px] uppercase tracking-[0.18em] text-[#64717a] font-medium text-${align}`}
    >
      {children}
    </th>
  );
}

