const MEDAL_STYLES: Record<number, { bg: string; label: string }> = {
  1: { bg: "bg-gradient-to-r from-[#D4A937] to-[#F0CF6E] text-[#3C2E05]", label: "Gold" },
  2: { bg: "bg-gradient-to-r from-[#9FA6AD] to-[#D5DADF] text-[#33383D]", label: "Silver" },
  3: { bg: "bg-gradient-to-r from-[#A96F3D] to-[#D19A66] text-[#3B2410]", label: "Bronze" },
};

function formatPeriod(startIso: string, endIso: string): string {
  const opts = {
    timeZone: "America/New_York",
    month: "short",
    day: "numeric",
  } as const;
  const start = new Date(startIso).toLocaleDateString("en-US", opts);
  // The period is exclusive of the next reset day, so show the day before.
  const endDate = new Date(new Date(endIso).getTime() - 1);
  const end = endDate.toLocaleDateString("en-US", { ...opts, year: "numeric" });
  return `${start} – ${end}`;
}

export default function AdminRankingsPage() {
  const [data, setData] = useState<RankingsPayload | null>(null);
  const [loading, setLoading] = useState(true);
  const [cycle, setCycle] = useState("");
  const [loadError, setLoadError] = useState<string | null>(null);
  const requestId = useRef(0);
  // Prize editing — values as strings so the inputs stay friendly.
  const [editingPrizes, setEditingPrizes] = useState(false);
  const [prizeDraft, setPrizeDraft] = useState<string[]>(["", "", ""]);
  const [prizeSaving, setPrizeSaving] = useState(false);
  const [prizeError, setPrizeError] = useState<string | null>(null);

  const load = useCallback(async () => {
    const id = ++requestId.current;
    setLoading(true);
    setLoadError(null);
    try {
      const res = await fetch(`/api/affiliates/admin/rankings${cycle ? `?cycle=${encodeURIComponent(cycle)}` : ""}`, {
        credentials: "include", cache: "no-store",
      });
      if (!res.ok) throw new Error("Could not load rankings. Please retry.");
      const payload = await res.json();
      if (id === requestId.current) setData(payload);
    } catch {
      if (id === requestId.current) { setData(null); setLoadError("Could not load rankings. Please retry."); }
    } finally {
      if (id === requestId.current) setLoading(false);
    }
  }, [cycle]);

  useEffect(() => {
    load();
  }, [load]);

  function startEditingPrizes() {
    const current = data?.prizes ?? [500, 100, 50];
    setPrizeDraft(current.map((p) => String(p)));
    setPrizeError(null);
    setEditingPrizes(true);
  }

  async function savePrizes() {
    const prizes = prizeDraft.map((p) => Number(p));
    if (prizes.some((p) => !Number.isFinite(p) || p < 0)) {
      setPrizeError("Enter a valid amount (0 or more) for each spot.");
      return;
    }
    if (prizes[0] < prizes[1] || prizes[1] < prizes[2]) {
      setPrizeError("Prizes must not increase down the ranks (#1 ≥ #2 ≥ #3).");
      return;
    }
    setPrizeSaving(true);
    setPrizeError(null);
    try {
      const res = await nonproviderMutationFetch("/api/affiliates/admin/rankings", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ prizes }),
      });
      const payload = await res.json().catch(() => ({}));
      if (!res.ok) {
        setPrizeError(
          payload?.error?.message || payload?.error || "Failed to save prizes"
        );
        return;
      }
      setEditingPrizes(false);
      await load();
    } catch {
      setPrizeError("Failed to save prizes");
    } finally {
      setPrizeSaving(false);
    }
  }

  const showingResults = !loading && !!data && (!cycle || cycle === data.cycleKey);
  const entries = showingResults ? data.entries : [];
  const withSales = entries.filter((e) => e.salesVolume > 0);
  const withoutSales = entries.filter((e) => e.salesVolume <= 0);

  return (
    <>
      <PageHeader
        eyebrow="Affiliate of the month"
        title="Monthly rankings"
        description={
          showingResults
            ? `Sales volume from attributed orders · ${formatPeriod(
                data.periodStart,
                data.periodEnd
              )} · ${(() => {
                if (data.source !== "live") return "closed cycle";
                const d = Math.max(
                  0,
                  Math.ceil(
                    (new Date(data.periodEnd).getTime() - Date.now()) /
                      86_400_000
                  )
                );
                return d <= 1 ? "last day" : `${d} days left`;
              })()} · resets on the ${data.resetDay}th, everyone starts from zero. Prizes require a $${data.qualifyingMinimum.toLocaleString()} sales minimum.`
            : "Sales volume from attributed orders. Resets on the 13th of each month. Prizes require a $1,500 sales minimum."
        }
        actions={
          <button
            onClick={load}
            className="inline-flex items-center gap-2 rounded-full px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526]/5 text-[#20282c] hover:bg-[#242526]/10 transition-colors"
          >
            <RefreshCw className={`h-3.5 w-3.5 ${loading ? "animate-spin" : ""}`} />
            Refresh
          </button>
        }
      />

      <div className="mb-6 flex flex-wrap items-center gap-3">
        <label htmlFor="ranking-cycle" className="text-sm font-medium">Contest cycle</label>
        <select id="ranking-cycle" value={cycle || data?.currentCycleKey || ""}
          onChange={e => { setLoading(true); setCycle(e.target.value); setEditingPrizes(false); }}
          className="rounded-xl border border-black/15 bg-white px-3 py-2 text-sm">
          {(data?.availableCycles ?? []).map(c => <option key={c.key} value={c.key}>
            {formatPeriod(c.start, c.end)}{c.key === data?.currentCycleKey ? " · Current" : ""}
          </option>)}
        </select>
        {loading && <span className="text-sm" role="status">Loading…</span>}
        {loadError && <p role="alert" className="text-sm text-red-600">{loadError}</p>}
        {!loading && data && <p className="w-full text-sm text-[#64717a]">
          {data.source === "snapshot"
            ? "Finalized snapshot — rankings and prizes are locked. Qualified prizes were added to payout balances; payment is still recorded manually."
            : data.source === "reconstructed"
              ? "Reconstructed history — calculated from currently available orders and affiliate status, not a finalized result. This view does not award prizes."
              : "Live rankings — prizes are not earned until the cycle closes and settlement completes."}
        </p>}
      </div>

      {showingResults && <>
      {/* Prize strip */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-3">
        {[1, 2, 3].map((rank) => (
          <div
            key={rank}
            className={`rounded-lg px-6 py-5 ${MEDAL_STYLES[rank].bg} shadow-sm`}
          >
            <p className="text-[10px] uppercase tracking-[0.18em] font-sans opacity-70">
              {MEDAL_STYLES[rank].label} · #{rank}
            </p>
            {editingPrizes ? (
              <div className="flex items-center gap-1.5 mt-1">
                <span className="font-sans text-2xl font-semibold">$</span>
                <input
                  type="number"
                  min="0"
                  step="10"
                  value={prizeDraft[rank - 1]}
                  onChange={(e) =>
                    setPrizeDraft((d) => {
                      const next = [...d];
                      next[rank - 1] = e.target.value;
                      return next;
                    })
                  }
                  className="w-full max-w-[120px] bg-white/40 border border-black/15 rounded-xl px-3 py-1 font-sans text-2xl font-semibold focus:outline-none focus:border-black/40"
                />
              </div>
            ) : (
              <p className="font-sans text-2xl font-semibold mt-1">
                ${data?.prizes?.[rank - 1] ?? [500, 100, 50][rank - 1]}
              </p>
            )}
            <p className="text-xs mt-1 opacity-80">
              {(() => {
                const holder = entries.find(
                  (e) => e.rank === rank && e.salesVolume > 0
                );
                if (!holder) return data?.source === "live" ? "Up for grabs" : "No qualifying winner";
                return holder.qualified
                  ? holder.name
                  : `${holder.name} · below $${(
                      data?.qualifyingMinimum ?? 1500
                    ).toLocaleString()} min`;
              })()}
            </p>
          </div>
        ))}
      </div>

      {/* Prize controls */}
      <div className="flex flex-wrap items-center gap-3 mb-8">
        {editingPrizes ? (
          <>
            <button
              onClick={savePrizes}
              disabled={prizeSaving}
              className="inline-flex items-center gap-2 rounded-full px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526] text-white hover:bg-[#20282c] transition-colors disabled:opacity-50"
            >
              {prizeSaving ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <Check className="h-3.5 w-3.5" />
              )}
              Save prizes
            </button>
            <button
              onClick={() => {
                setEditingPrizes(false);
                setPrizeError(null);
              }}
              disabled={prizeSaving}
              className="inline-flex items-center gap-2 rounded-full px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526]/5 text-[#20282c] hover:bg-[#242526]/10 transition-colors"
            >
              <X className="h-3.5 w-3.5" />
              Cancel
            </button>
            <span className="text-xs text-[#64717a]">
              Applies from the current cycle onward — affiliates see the new
              amounts right away. Past cycles keep the prizes they ran with.
            </span>
            {prizeError && (
              <span className="text-xs text-red-600">{prizeError}</span>
            )}
          </>
        ) : (
          <button
            onClick={startEditingPrizes}
            disabled={loading || !data || data.source !== "live"}
            className="inline-flex items-center gap-2 rounded-full px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526]/5 text-[#20282c] hover:bg-[#242526]/10 transition-colors"
          >
            <Pencil className="h-3 w-3" />
            Edit prizes
          </button>
        )}
      </div>

      </>}
      <section className="glass-surface rounded-lg overflow-hidden">
        {loading ? (
          <div className="p-10 text-center text-sm text-[#64717a]">Loading…</div>
        ) : withSales.length === 0 ? (
          <EmptyState
            icon={Trophy}
            title="No attributed sales yet this cycle"
            description="Rankings fill up as orders come in with affiliate codes. Everyone starts from zero each cycle."
          />
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm min-w-[560px]">
              <thead>
                <tr className="border-b border-[#242526]/8 text-left">
                  <th className="py-3.5 px-5 font-sans text-[10px] uppercase tracking-[0.18em] text-[#64717a] font-medium">Rank</th>
                  <th className="py-3.5 px-5 font-sans text-[10px] uppercase tracking-[0.18em] text-[#64717a] font-medium">Affiliate</th>
                  <th className="py-3.5 px-5 font-sans text-[10px] uppercase tracking-[0.18em] text-[#64717a] font-medium">Code</th>
                  <th className="py-3.5 px-5 font-sans text-[10px] uppercase tracking-[0.18em] text-[#64717a] font-medium text-right">Orders</th>
                  <th className="py-3.5 px-5 font-sans text-[10px] uppercase tracking-[0.18em] text-[#64717a] font-medium text-right">Sales volume</th>
                  <th className="py-3.5 px-5 font-sans text-[10px] uppercase tracking-[0.18em] text-[#64717a] font-medium text-right">Prize</th>
                </tr>
              </thead>
              <tbody>
                {withSales.map((e) => (
                  <tr
                    key={e.affiliateId}
                    className="border-b border-[#242526]/5 last:border-0 hover:bg-[#242526]/2"
                  >
                    <td className="py-3.5 px-5">
                      {e.rank <= 3 ? (
                        <span
                          className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-[10px] uppercase tracking-[0.14em] font-sans font-semibold ${MEDAL_STYLES[e.rank].bg}`}
                        >
                          <Trophy className="h-3 w-3" />#{e.rank}
                        </span>
                      ) : (
                        <span className="font-sans text-[#64717a]">#{e.rank}</span>
                      )}
                    </td>
                    <td className="py-3.5 px-5 font-medium">{e.name}</td>
                    <td className="py-3.5 px-5 font-sans text-xs">{e.promoCode}</td>
                    <td className="py-3.5 px-5 text-right font-sans">{e.orders}</td>
                    <td className="py-3.5 px-5 text-right font-sans font-medium">
                      {formatCurrency(e.salesVolume)}
                    </td>
                    <td className="py-3.5 px-5 text-right font-sans">
                      {e.prize ? `$${e.prize}` : "—"}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>

      {withoutSales.length > 0 && (
        <p className="text-xs text-[#64717a] mt-4">
          {withoutSales.length} active affiliate
          {withoutSales.length === 1 ? "" : "s"} with no attributed sales yet
          this cycle.
        </p>
      )}
    </>
  );
}

"use client";
// BODY COMMAND ADAPTER
import { canonicalActionFetch as fetch } from "@/lib/affiliates/canonical-action-fetch";

import { useEffect, useState, useCallback } from "react";
import {
  Inbox,
  Check,
  X,
  ExternalLink,
  ArrowRight,
  AlertCircle,
  UserPlus,
} from "lucide-react";
import {
  PageHeader,
  Pill,
  EmptyState,
  formatShortDate,
} from "@/components/affiliates/shared/ui";

interface SuggestedReferrer {
  id: string;
  name: string;
  promoCode: string;
  source: "invite-link";
}

interface RequestRow {
  referralCommissionRate?: number | null;
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  whatsapp?: string;
  promoCode: string;
  instagram?: string;
  tiktok?: string;
  website?: string;
  createdAt: string;
  suggestedReferrer?: SuggestedReferrer | null;
}

interface ReferrerOption {
  id: string;
  name: string;
  promoCode: string;
  isAdmin?: boolean;
}

export default function AdminRequestsPage() {
  const [requests, setRequests] = useState<RequestRow[]>([]);
  const [referrers, setReferrers] = useState<ReferrerOption[]>([]);
  const [loading, setLoading] = useState(true);
  const [active, setActive] = useState<RequestRow | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/affiliates/admin/requests", {
        credentials: "include",
      });
      if (res.ok) {
        const data = await res.json();
        setRequests(data.requests ?? []);
        setReferrers(data.referrerOptions ?? []);
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  return (
    <>
      <PageHeader
        eyebrow="Onboarding"
        title="Affiliate requests"
        description="Approve new affiliates, set their commission rate and optionally credit a referrer."
        actions={
          <span className="inline-flex items-center gap-2 glass-surface rounded-full px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
            <Inbox className="h-3.5 w-3.5" />
            {requests.length} pending
          </span>
        }
      />

      {loading ? (
        <div className="glass-surface rounded-lg p-12 text-center text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
          Loading…
        </div>
      ) : requests.length === 0 ? (
        <EmptyState
          icon={Inbox}
          title="Inbox zero"
          description="No pending applications. New requests will show up here as people sign up."
        />
      ) : (
        <ul className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {requests.map((r) => (
            <li
              key={r.id}
              className="glass-surface rounded-lg p-6 flex flex-col"
            >
              <div className="flex items-start justify-between gap-4">
                <div>
                  <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
                    {formatShortDate(r.createdAt)}
                  </p>
                  <h3 className="text-xl font-medium tracking-tight mt-1">
                    {r.firstName} {r.lastName}
                  </h3>
                  <p className="text-sm text-[#64717a] mt-0.5">{r.email}</p>
                </div>
                <Pill tone="warn">Pending</Pill>
              </div>

              {r.suggestedReferrer && (
                <div className="mt-4 inline-flex items-center gap-2 self-start rounded-full bg-[#20282c]/5 border border-[#20282c]/10 px-3 py-1.5">
                  <UserPlus className="h-3 w-3 text-[#20282c]" />
                  <span className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
                    Referred by
                  </span>
                  <span className="text-xs font-medium text-[#20282c]">
                    {r.suggestedReferrer.name}
                  </span>
                  <span className="text-xs font-sans text-[#64717a]">
                    · {r.suggestedReferrer.promoCode}
                  </span>
                </div>
              )}

              <dl className="grid grid-cols-2 gap-3 mt-5 text-sm">
                <Detail label="Phone" value={r.phone || "—"} />
                <Detail label="WhatsApp" value={r.whatsapp || "—"} />
                <Detail
                  label="Wanted code"
                  value={
                    <span className="font-sans text-[#20282c]">
                      {r.promoCode}
                    </span>
                  }
                />
                <Detail
                  label="Instagram"
                  value={r.instagram || "—"}
                  href={
                    r.instagram
                      ? `https://instagram.com/${r.instagram.replace(/^@/, "")}`
                      : undefined
                  }
                />
                <Detail label="TikTok" value={r.tiktok || "—"} />
                {r.website && (
                  <Detail
                    label="Website"
                    value={r.website}
                    href={
                      r.website.startsWith("http")
                        ? r.website
                        : `https://${r.website}`
                    }
                  />
                )}
              </dl>

              <div className="mt-6 flex gap-2 justify-end">
                <button
                  onClick={() => setActive(r)}
                  className="inline-flex items-center gap-1.5 rounded-full px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526] text-white hover:bg-[#20282c] transition-colors"
                >
                  Review
                  <ArrowRight className="h-3 w-3" />
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}

      {active && (
        <ReviewModal
          request={active}
          referrers={referrers}
          onClose={() => setActive(null)}
          onDone={() => {
            setActive(null);
            load();
          }}
        />
      )}
    </>
  );
}

function Detail({
  label,
  value,
  href,
}: {
  label: string;
  value: React.ReactNode;
  href?: string;
}) {
  return (
    <div>
      <dt className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
        {label}
      </dt>
      <dd className="mt-1 text-sm text-[#20282c]">
        {href ? (
          <a
            href={href}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-1 hover:underline"
          >
            {value}
            <ExternalLink className="h-3 w-3" />
          </a>
        ) : (
          value
        )}
      </dd>
    </div>
  );
}

function ReviewModal({
  request,
  referrers,
  onClose,
  onDone,
}: {
  request: RequestRow;
  referrers: ReferrerOption[];
  onClose: () => void;
  onDone: () => void;
}) {
  const [promoCode, setPromoCode] = useState(request.promoCode);
  const [commissionRate, setCommissionRate] = useState(15);
  const [recurringCommissionRate, setRecurringCommissionRate] = useState(10);
  const [couponRate, setCouponRate] = useState(15);
  const [referrerId, setReferrerId] = useState(
    request.suggestedReferrer?.id ?? ""
  );
  const [referralCommissionRate, setReferralCommissionRate] = useState(request.referralCommissionRate ?? 5);
  // Optional monthly sales bonus, off unless a target is entered.
  const [bonusThreshold, setBonusThreshold] = useState("");
  const [bonusRate, setBonusRate] = useState("5");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function approve(e: React.FormEvent) {
    e.preventDefault();
    if (!promoCode.trim()) {
      setError("Promo code cannot be empty.");
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`/api/affiliates/admin/requests/${request.id}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          promoCode: promoCode.trim(),
          commissionRate,
          recurringCommissionRate,
          couponRate,
          referrerId: referrerId || null,
          referralCommissionRate: referrerId ? referralCommissionRate : 0,
          bonusThreshold: Number(bonusThreshold) > 0 ? Number(bonusThreshold) : undefined,
          bonusRate:
            Number(bonusThreshold) > 0 && Number(bonusRate) > 0
              ? Number(bonusRate)
              : undefined,
        }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        setError(data?.error?.message || data.error || "Failed to approve");
        return;
      }
      onDone();
    } finally {
      setLoading(false);
    }
  }

  async function reject() {
    if (!window.confirm("Reject and delete this application?")) return;
    setLoading(true);
    try {
      const res = await fetch(`/api/affiliates/admin/requests/${request.id}`, {
        method: "DELETE",
        credentials: "include",
      });
      if (res.ok) onDone();
      // BODY COMMAND REJECTION STATE
      else { const data = await res.json(); setError(data.error || "Command not confirmed complete. Check Command recovery."); }
    } finally {
      setLoading(false);
    }
  }

  const inputClass =
    "bg-transparent border-0 border-b border-[#242526]/15 rounded-none px-0 py-2.5 text-sm focus:outline-none focus:border-[#242526] transition-colors placeholder:text-[#64717a] w-full";

  const referrer = referrers.find((r) => r.id === referrerId);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div
        className="absolute inset-0 bg-[#20282c]/50 backdrop-blur-sm"
        onClick={onClose}
      />
      <div className="relative glass-surface-strong rounded-lg p-7 md:p-9 max-w-md w-full max-h-[90vh] overflow-y-auto">
        <button
          onClick={onClose}
          className="absolute top-4 right-4 p-2 rounded-full hover:bg-[#242526]/5"
        >
          <X className="h-4 w-4" />
        </button>

        <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] mb-1">
          Review application
        </p>
        <h3 className="text-2xl font-medium tracking-tight">
          {request.firstName} {request.lastName}
        </h3>
        <p className="text-sm text-[#64717a] mt-0.5">{request.email}</p>

        {error && (
          <p className="text-amber-700 text-sm mt-5 p-3 bg-amber-50/80 border border-amber-200 rounded-xl flex gap-2 items-start">
            <AlertCircle className="h-4 w-4 mt-0.5 shrink-0" />
            {error}
          </p>
        )}

        <form onSubmit={approve} className="mt-6 space-y-1">
          <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] mb-2">
            Promo code
          </p>
          <div className="mb-5">
            <input
              type="text"
              value={promoCode}
              onChange={(e) =>
                setPromoCode(
                  e.target.value.replace(/[^a-zA-Z0-9]/g, "").toUpperCase().slice(0, 40)
                )
              }
              className={`${inputClass} font-sans tracking-wide`}
              placeholder="e.g. JANE15"
            />
            <p className="text-xs text-[#64717a] mt-1.5 leading-relaxed">
              {promoCode === request.promoCode ? (
                <>This is the code they asked for — edit it if you want something different.</>
              ) : (
                <>
                  Changed from{" "}
                  <span className="font-sans line-through opacity-70">
                    {request.promoCode}
                  </span>{" "}
                  — the approval email and checkout coupon will use{" "}
                  <span className="font-sans text-[#20282c]">{promoCode || "…"}</span>.
                </>
              )}
            </p>
          </div>

          <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] mb-2">
            Rates
          </p>
          <div className="grid grid-cols-2 gap-4 mb-1">
            <label className="block">
              <span className="text-xs text-[#64717a]">Coupon discount</span>
              <div className="flex items-center gap-2">
                <input
                  type="number"
                  step="0.5"
                  min="0"
                  max="100"
                  value={couponRate}
                  onChange={(e) =>
                    setCouponRate(Math.max(0, Number(e.target.value) || 0))
                  }
                  className={inputClass}
                />
                <span className="text-sm text-[#64717a] font-sans">%</span>
              </div>
            </label>
            <label className="block">
              <span className="text-xs text-[#64717a]">First-order commission</span>
              <div className="flex items-center gap-2">
                <input
                  type="number"
                  step="0.5"
                  min="0"
                  max="100"
                  value={commissionRate}
                  onChange={(e) =>
                    setCommissionRate(Math.max(0, Number(e.target.value) || 0))
                  }
                  className={inputClass}
                />
                <span className="text-sm text-[#64717a] font-sans">%</span>
              </div>
            </label>
            <label className="block">
              <span className="text-xs text-[#64717a]">Recurring commission</span>
              <div className="flex items-center gap-2">
                <input
                  type="number"
                  step="0.5"
                  min="0"
                  max="100"
                  value={recurringCommissionRate}
                  onChange={(e) =>
                    setRecurringCommissionRate(
                      Math.max(0, Number(e.target.value) || 0)
                    )
                  }
                  className={inputClass}
                />
                <span className="text-sm text-[#64717a] font-sans">%</span>
              </div>
            </label>
          </div>
          <p className="text-xs text-[#64717a] mb-6 leading-relaxed">
            Customers get {couponRate}% off with code{" "}
            <span className="font-sans text-[#20282c]">{promoCode || request.promoCode}</span>.
            {request.firstName} earns {commissionRate}% on a customer&apos;s first
            order and {recurringCommissionRate}% on their recurring orders.
          </p>

          <div className="rounded-lg bg-[#242526]/4 border border-[#242526]/8 p-4 !mt-4 mb-4">
            <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] mb-2">
              Monthly sales bonus (optional)
            </p>
            <div className="grid grid-cols-2 gap-4">
              <label className="block">
                <span className="text-xs text-[#64717a]">Sales target / month</span>
                <div className="flex items-center gap-2">
                  <span className="text-sm text-[#64717a] font-sans">$</span>
                  <input
                    type="number"
                    min="0"
                    step="100"
                    value={bonusThreshold}
                    onChange={(e) => setBonusThreshold(e.target.value)}
                    placeholder="e.g. 5000"
                    className={inputClass}
                  />
                </div>
              </label>
              <label className="block">
                <span className="text-xs text-[#64717a]">Bonus</span>
                <div className="flex items-center gap-2">
                  <input
                    type="number"
                    step="0.5"
                    min="0"
                    max="100"
                    value={bonusRate}
                    onChange={(e) => setBonusRate(e.target.value)}
                    className={inputClass}
                  />
                  <span className="text-sm text-[#64717a] font-sans">%</span>
                </div>
              </label>
            </div>
            <p className="text-xs text-[#64717a] mt-2 leading-relaxed">
              {Number(bonusThreshold) > 0 ? (
                <>
                  If {request.firstName} sells ${Number(bonusThreshold).toLocaleString()}+
                  in a calendar month, they earn an extra {Number(bonusRate) || 0}% on
                  that month&apos;s sales. They&apos;ll see a progress bar on their
                  dashboard.
                </>
              ) : (
                <>Leave the target empty for no bonus program.</>
              )}
            </p>
          </div>

          <div className="rounded-lg bg-[#242526]/4 border border-[#242526]/8 p-4 !mt-4">
            <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] mb-2">
              Referred by (optional)
            </p>
            {request.suggestedReferrer && (
              <p className="text-xs text-[#20282c] mb-2 inline-flex items-center gap-1.5 bg-[#20282c]/5 px-2 py-1 rounded-full">
                <UserPlus className="h-3 w-3" />
                Pre-selected from invite link
              </p>
            )}
            <select
              value={referrerId}
              onChange={(e) => setReferrerId(e.target.value)}
              className={`${inputClass} cursor-pointer`}
            >
              <option value="">— Nobody —</option>
              {referrers.map((r) => (
                <option key={r.id} value={r.id}>
                  {r.isAdmin
                    ? `${r.name} — Admin (house account)`
                    : `${r.name} (${r.promoCode})`}
                </option>
              ))}
            </select>

            {referrerId && (
              <>
                <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] mt-5 mb-2">
                  Referrer's cut
                </p>
                <div className="flex items-center gap-2 mb-1">
                  <input
                    type="number"
                    step="0.5"
                    min="0"
                    max="50"
                    value={referralCommissionRate}
                    onChange={(e) =>
                      setReferralCommissionRate(
                        Math.max(0, Number(e.target.value) || 0)
                      )
                    }
                    className={inputClass}
                  />
                  <span className="text-sm text-[#64717a] font-sans">%</span>
                </div>
                <p className="text-xs text-[#64717a] mt-2 leading-relaxed">
                  We'll automatically credit{" "}
                  <span className="font-sans text-[#20282c]">
                    {referrer?.name}
                  </span>{" "}
                  with {referralCommissionRate}% of every order{" "}
                  {request.firstName} brings in — on top of the{" "}
                  {commissionRate}% paid to {request.firstName}.
                </p>
              </>
            )}
          </div>

          <div className="!mt-8 flex gap-3">
            <button
              type="button"
              onClick={reject}
              disabled={loading}
              className="inline-flex items-center justify-center gap-1.5 rounded-full px-5 py-3 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#64717a]/10 text-[#64717a] hover:bg-[#64717a]/15 transition-colors"
            >
              <X className="h-3.5 w-3.5" />
              Reject
            </button>
            <button
              type="submit"
              disabled={loading}
              className="flex-1 inline-flex items-center justify-center gap-2 rounded-full py-3 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526] text-white hover:bg-[#20282c] transition-colors disabled:opacity-50"
            >
              <Check className="h-3.5 w-3.5" />
              {loading ? "Approving…" : "Approve"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

