/**
 * Edit the products a plan ships each cycle without cancelling it. Changes only
 * take effect on the next renewal (nothing is charged on save); prices come
 * from the live catalog at charge time.
 */
function ItemsEditor({
  sub,
  catalog,
  busy,
  onSave,
}: {
  sub: AdminSubscription;
  catalog: CatalogProduct[];
  busy: string | null;
  onSave: (items: { productId: number; quantity: number }[]) => void;
}) {
  const [items, setItems] = useState<SubscriptionLine[]>(() =>
    sub.items.map((i) => ({ ...i }))
  );
  const [addId, setAddId] = useState("");

  // Re-sync with the saved list after a reload (e.g. right after saving).
  const savedKey = JSON.stringify(sub.items.map((i) => [i.productId, i.quantity]));
  useEffect(() => {
    setItems(sub.items.map((i) => ({ ...i })));
    setAddId("");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sub.id, savedKey]);

  const dirty =
    savedKey !== JSON.stringify(items.map((i) => [i.productId, i.quantity]));

  const inList = new Set(items.map((i) => i.productId));
  const addable = catalog.filter((p) => !inList.has(p.id));
  const priceById = useMemo(
    () => new Map(catalog.map((p) => [p.id, p.price])),
    [catalog]
  );

  // Estimated discounted product subtotal (shipping excluded — it's stored
  // separately on the plan). Only shown when every line can be priced.
  const estimate = useMemo(() => {
    let subtotal = 0;
    for (const item of items) {
      const price = priceById.get(item.productId);
      if (price == null || price <= 0) return null;
      subtotal += price * item.quantity;
    }
    return subtotal * (1 - (sub.discountPercent || 0) / 100);
  }, [items, priceById, sub.discountPercent]);

  const setQty = (productId: number, delta: number) => {
    setItems((prev) =>
      prev.map((i) =>
        i.productId === productId
          ? { ...i, quantity: Math.min(50, Math.max(1, i.quantity + delta)) }
          : i
      )
    );
  };

  const addProduct = () => {
    const id = parseInt(addId, 10);
    const product = catalog.find((p) => p.id === id);
    if (!product) return;
    setItems((prev) => [
      ...prev,
      { productId: product.id, name: product.name, quantity: 1 },
    ]);
    setAddId("");
  };

  return (
    <div className="mt-6">
      <label className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] mb-2 block">
        Products per delivery
      </label>
      <div className="rounded-lg border border-[#242526]/10 bg-white/50 divide-y divide-[#242526]/6">
        {items.map((item) => (
          <div key={item.productId} className="flex items-center gap-3 px-3.5 py-2.5">
            <div className="min-w-0 flex-1">
              <p className="text-sm leading-snug truncate">{item.name}</p>
              {priceById.get(item.productId) != null && (
                <p className="text-[11px] text-[#64717a] font-sans">
                  {formatCurrency(priceById.get(item.productId) ?? 0)} each
                </p>
              )}
            </div>
            <div className="flex items-center gap-1 shrink-0">
              <button
                onClick={() => setQty(item.productId, -1)}
                disabled={item.quantity <= 1}
                className="p-1.5 rounded-full bg-[#242526]/5 hover:bg-[#242526]/10 disabled:opacity-30 transition-colors"
                aria-label="Decrease quantity"
              >
                <Minus className="h-3 w-3" />
              </button>
              <span className="w-7 text-center text-sm font-sans">{item.quantity}</span>
              <button
                onClick={() => setQty(item.productId, 1)}
                className="p-1.5 rounded-full bg-[#242526]/5 hover:bg-[#242526]/10 transition-colors"
                aria-label="Increase quantity"
              >
                <Plus className="h-3 w-3" />
              </button>
            </div>
            <button
              onClick={() =>
                setItems((prev) => prev.filter((i) => i.productId !== item.productId))
              }
              disabled={items.length <= 1}
              className="p-1.5 rounded-full text-red-600 bg-red-500/10 hover:bg-red-500/15 disabled:opacity-30 disabled:cursor-not-allowed transition-colors shrink-0"
              aria-label="Remove product"
              title={items.length <= 1 ? "A plan needs at least one product" : "Remove"}
            >
              <Trash2 className="h-3.5 w-3.5" />
            </button>
          </div>
        ))}
        {items.length === 0 && (
          <p className="px-3.5 py-3 text-sm text-[#64717a]">
            Add at least one product below.
          </p>
        )}
      </div>

      <div className="mt-2 flex items-center gap-2">
        <select
          value={addId}
          onChange={(e) => setAddId(e.target.value)}
          className="flex-1 min-w-0 rounded-xl border border-[#242526]/12 bg-white/70 px-3 py-2.5 text-sm outline-none focus:border-[#242526]/40"
        >
          <option value="">Add a product…</option>
          {addable.map((p) => (
            <option key={p.id} value={p.id}>
              {p.name}
              {p.price > 0 ? ` — ${formatCurrency(p.price)}` : ""}
            </option>
          ))}
        </select>
        <button
          onClick={addProduct}
          disabled={!addId}
          className="inline-flex items-center gap-1.5 rounded-xl px-4 py-2.5 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526]/5 text-[#20282c] hover:bg-[#242526]/10 transition-colors disabled:opacity-40 disabled:cursor-not-allowed shrink-0"
        >
          <Plus className="h-3 w-3" /> Add
        </button>
      </div>

      <div className="mt-3 flex items-center justify-between gap-3">
        <p className="text-[11px] text-[#64717a]">
          {estimate != null && items.length > 0 ? (
            <>
              ≈ {formatCurrency(estimate)}/charge after {Math.round(sub.discountPercent)}%
              discount, + shipping.{" "}
            </>
          ) : null}
          Applies from the next renewal — nothing is charged now.
        </p>
        <button
          onClick={() =>
            onSave(items.map((i) => ({ productId: i.productId, quantity: i.quantity })))
          }
          disabled={busy != null || !dirty || items.length === 0}
          className="shrink-0 rounded-xl px-4 py-2.5 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526] text-white hover:bg-[#20282c] transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
        >
          {busy === "set_items" ? "Saving…" : "Save products"}
        </button>
      </div>
    </div>
  );
}

function SubscriptionDrawer({
  sub,
  catalog,
  onClose,
  onChanged,
}: {
  sub: AdminSubscription;
  catalog: CatalogProduct[];
  onClose: () => void;
  onChanged: () => Promise<void> | void;
}) {
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [freq, setFreq] = useState(sub.intervalDays);
  const [pauseDays, setPauseDays] = useState(0);

  const runAction = useCallback(
    async (action: string, extra?: Record<string, unknown>, confirmMsg?: string) => {
      if (confirmMsg && !window.confirm(confirmMsg)) return;
      setBusy(action);
      setError(null);
      setNotice(null);
      try {
        const res = await providerMutationFetch(`/api/affiliates/admin/subscriptions/${sub.id}`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          credentials: "include",
          body: JSON.stringify({ action, ...extra }),
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok || data?.ok === false) {
          setError(data?.error || "Action failed.");
          return;
        }
        if (action === "charge_now") {
          setNotice(`Charged successfully — order #${data.wooOrderId} ($${data.total}).`);
        }
        if (action === "set_items") {
          setNotice("Products updated — the next renewal will ship the new items.");
        }
        if (action === "pause") {
          setNotice(
            data.pausedUntil
              ? `Paused — automatically resumes ${formatShortDate(data.pausedUntil)}.`
              : "Paused until you resume it manually."
          );
        }
        if (action === "refund") {
          const n = Number(data.commissionsVoided ?? 0);
          setNotice(
            n > 0
              ? `Marked refunded — removed ${n} unpaid affiliate commission${
                  n === 1 ? "" : "s"
                }.`
              : "Marked refunded. No unpaid affiliate commission to remove."
          );
        }
        await onChanged();
      } catch {
        setError("Action failed. Please try again.");
      } finally {
        setBusy(null);
      }
    },
    [sub.id, onChanged]
  );

  const isCancelled = sub.status === "cancelled";
  const isEnded = sub.status === "cancelled" || sub.status === "refunded";
  const canPause = ["active", "past_due", "charging"].includes(sub.status);
  const canResume = ["paused", "past_due"].includes(sub.status);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-[#20282c]/50 backdrop-blur-sm" onClick={onClose} />
      <div className="relative glass-surface-strong rounded-lg p-7 md:p-9 max-w-xl w-full max-h-[92vh] overflow-y-auto">
        <button
          onClick={onClose}
          className="absolute top-4 right-4 p-2 rounded-full hover:bg-[#242526]/5"
          aria-label="Close"
        >
          <X className="h-4 w-4" />
        </button>

        <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] mb-1">
          Subscription · {subscriptionIntervalLabel(sub.intervalDays)}
        </p>
        <h3 className="text-2xl font-medium tracking-tight">{sub.customerName}</h3>
        <p className="text-sm text-[#64717a] mt-0.5">{sub.customerEmail}</p>

        <div className="mt-3 flex items-center gap-2">
          <Pill tone={statusTone(sub.status)}>{statusLabel(sub.status)}</Pill>
          <Pill tone="neutral">{sub.provider === "stripe" ? "Stripe" : "Square"}</Pill>
        </div>

        {/* Charge health */}
        <div
          className={`mt-5 rounded-lg border p-4 ${
            sub.status === "past_due" || sub.status === "paused"
              ? "bg-amber-500/10 border-amber-600/20"
              : "bg-emerald-500/8 border-emerald-600/15"
          }`}
        >
          <div className="flex items-center gap-2 text-sm font-medium text-[#20282c]">
            {sub.status === "past_due" || sub.status === "paused" ? (
              <AlertCircle className="h-4 w-4 text-amber-600" />
            ) : (
              <CheckCircle2 className="h-4 w-4 text-emerald-600" />
            )}
            {sub.status === "paused"
              ? sub.pausedUntil
                ? `Paused — resumes ${formatShortDate(sub.pausedUntil)}`
                : sub.failedAttempts > 0
                  ? "Paused after failed charges"
                  : "Paused until manually resumed"
              : sub.status === "past_due"
                ? "Last charge failed — retrying automatically"
                : sub.lastChargedAt
                  ? "Last charge went through"
                  : "Awaiting first renewal"}
          </div>
          {sub.lastError && (sub.status === "past_due" || sub.status === "paused") && (
            <p className="text-[12px] text-[#64717a] mt-1.5">{sub.lastError}</p>
          )}
          {sub.failedAttempts > 0 && (
            <p className="text-[11px] text-[#64717a] mt-1">
              {sub.failedAttempts} failed {sub.failedAttempts === 1 ? "attempt" : "attempts"}
            </p>
          )}
        </div>

        <div className="mt-5">
          {isEnded && <Row label="Items" value={itemsLabel(sub.items)} />}
          <Row label="Discount" value={`${Math.round(sub.discountPercent)}% (Subscribe & Save)`} />
          <Row label="Frequency" value={subscriptionIntervalLabel(sub.intervalDays)} />
          <Row
            label="Next order"
            value={
              ACTIVE_STATUSES.has(sub.status)
                ? `${formatShortDate(sub.nextBillingAt)} · ${formatChargeTime(sub.nextBillingAt)}`
                : sub.status === "paused" && sub.pausedUntil
                  ? `Paused — resumes ${formatShortDate(sub.pausedUntil)}`
                  : "—"
            }
          />
          <Row
            label="Last charged"
            value={sub.lastChargedAt ? formatShortDate(sub.lastChargedAt) : "Never"}
          />
          <Row
            label="Affiliate"
            value={
              sub.affiliate ? (
                <span className="inline-flex items-center gap-1.5">
                  <Tag className="h-3.5 w-3.5 text-[#64717a]" />
                  {sub.affiliate.name}
                  {sub.affiliate.code ? (
                    <span className="font-sans uppercase text-[#64717a]">
                      ({sub.affiliate.code})
                    </span>
                  ) : null}
                </span>
              ) : (
                "None"
              )
            }
          />
          <Row
            label="Card"
            value={
              <span className="inline-flex items-center gap-1.5">
                <CreditCard className="h-3.5 w-3.5 text-[#64717a]" />
                {cardLabel(sub)}
              </span>
            }
          />
          <Row
            label="Ships to"
            value={
              [sub.shipping.city, sub.shipping.state, sub.shipping.postcode, sub.shipping.country]
                .filter(Boolean)
                .join(", ") || "—"
            }
          />
          <Row label="First order" value={sub.firstOrderId ? `#${sub.firstOrderId}` : "—"} />
          <Row label="Latest order" value={sub.lastOrderId ? `#${sub.lastOrderId}` : "—"} />
          <Row label="Started" value={formatShortDate(sub.createdAt)} />
          {sub.cancelledAt && (
            <Row
              label={sub.status === "refunded" ? "Refunded" : "Cancelled"}
              value={formatShortDate(sub.cancelledAt)}
            />
          )}
        </div>

        {error && <p className="mt-4 text-sm text-red-600">{error}</p>}
        {notice && <p className="mt-4 text-sm text-emerald-700">{notice}</p>}

        {!isEnded && (
          <>
            {/* Edit products */}
            <ItemsEditor
              sub={sub}
              catalog={catalog}
              busy={busy}
              onSave={(items) => runAction("set_items", { items })}
            />

            {/* Change frequency */}
            <div className="mt-6">
              <label className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a] mb-2 block">
                Delivery frequency
              </label>
              <div className="flex items-center gap-2">
                <select
                  value={freq}
                  onChange={(e) => setFreq(parseInt(e.target.value, 10))}
                  className="flex-1 rounded-xl border border-[#242526]/12 bg-white/70 px-3 py-2.5 text-sm outline-none focus:border-[#242526]/40"
                >
                  {SUBSCRIPTION_INTERVAL_OPTIONS.map((o) => (
                    <option key={o.days} value={o.days}>
                      {o.label}
                    </option>
                  ))}
                </select>
                <button
                  onClick={() => runAction("set_interval", { intervalDays: freq })}
                  disabled={busy != null || freq === sub.intervalDays}
                  className="rounded-xl px-4 py-2.5 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526]/5 text-[#20282c] hover:bg-[#242526]/10 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
                >
                  {busy === "set_interval" ? "Saving…" : "Update"}
                </button>
              </div>
            </div>

            {/* Actions */}
            <div className="mt-6 flex flex-wrap gap-3">
              <button
                onClick={() =>
                  runAction(
                    "charge_now",
                    undefined,
                    "Charge this subscription's saved card right now and create a new order?"
                  )
                }
                disabled={busy != null}
                className="flex-1 min-w-[150px] inline-flex items-center justify-center gap-2 rounded-full py-3 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526] text-white hover:bg-[#20282c] transition-colors disabled:opacity-50"
              >
                {busy === "charge_now" ? (
                  <>
                    <Loader2 className="h-3.5 w-3.5 animate-spin" /> Charging…
                  </>
                ) : (
                  <>
                    <Zap className="h-3.5 w-3.5" /> Charge now
                  </>
                )}
              </button>

              {canPause && (
                <div className="inline-flex items-center rounded-full bg-[#242526]/5 pl-1 pr-1 py-1 gap-1">
                  <select
                    value={pauseDays}
                    onChange={(e) => setPauseDays(parseInt(e.target.value, 10))}
                    disabled={busy != null}
                    className="rounded-full bg-transparent px-3 py-2 text-[10px] uppercase tracking-[0.14em] font-sans text-[#20282c] outline-none cursor-pointer"
                    aria-label="Pause length"
                  >
                    <option value={0}>Until resumed</option>
                    <option value={7}>1 week</option>
                    <option value={14}>2 weeks</option>
                    <option value={30}>1 month</option>
                    <option value={60}>2 months</option>
                    <option value={90}>3 months</option>
                  </select>
                  <button
                    onClick={() =>
                      runAction("pause", pauseDays > 0 ? { pauseDays } : undefined)
                    }
                    disabled={busy != null}
                    className="inline-flex items-center justify-center gap-2 rounded-full px-4 py-2 text-[10px] uppercase tracking-[0.18em] font-sans bg-white text-[#20282c] hover:bg-[#242526]/10 transition-colors disabled:opacity-50"
                  >
                    <Pause className="h-3.5 w-3.5" /> Pause
                  </button>
                </div>
              )}
              {canResume && (
                <button
                  onClick={() => runAction("resume")}
                  disabled={busy != null}
                  className="inline-flex items-center justify-center gap-2 rounded-full px-5 py-3 text-[10px] uppercase tracking-[0.18em] font-sans bg-[#242526]/5 text-[#20282c] hover:bg-[#242526]/10 transition-colors disabled:opacity-50"
                >
                  <Play className="h-3.5 w-3.5" /> Resume
                </button>
              )}
              <button
                onClick={() =>
                  runAction(
                    "cancel",
                    undefined,
                    "Cancel this subscription permanently? This stops all future orders."
                  )
                }
                disabled={busy != null}
                className="inline-flex items-center justify-center gap-2 rounded-full px-5 py-3 text-[10px] uppercase tracking-[0.18em] font-sans bg-red-500/10 text-red-600 hover:bg-red-500/15 transition-colors disabled:opacity-50"
              >
                <Ban className="h-3.5 w-3.5" /> Cancel
              </button>
            </div>
          </>
        )}

        {sub.status !== "refunded" && (
          <div className="mt-3 flex flex-wrap gap-3">
            <button
              onClick={() =>
                runAction(
                  "refund",
                  undefined,
                  "Mark this subscription as refunded? This stops billing and removes any unpaid affiliate commission for its orders."
                )
              }
              disabled={busy != null}
              className="inline-flex items-center justify-center gap-2 rounded-full px-5 py-3 text-[10px] uppercase tracking-[0.18em] font-sans bg-red-500/10 text-red-600 hover:bg-red-500/15 transition-colors disabled:opacity-50"
            >
              {busy === "refund" ? (
                <>
                  <Loader2 className="h-3.5 w-3.5 animate-spin" /> Refunding…
                </>
              ) : (
                <>
                  <Ban className="h-3.5 w-3.5" /> Mark refunded
                </>
              )}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";
import {nonproviderMutationFetch} from "@/lib/affiliates/nonprovider-mutation-fetch";
import { useLatestRead } from "@/lib/affiliates/use-latest-read";

/**
 * Admin — TikTok bonus monitoring. Every active affiliate with their video
 * count for the current 30-day cycle, streak position and the reward they're
 * playing for. The goal is fixed at 15 videos per cycle; the reward ladder
 * (amount per consecutive streak cycle, resetting on a missed cycle) is
 * editable here. Bonuses are paid automatically when each cycle closes.
 */

import { useCallback, useEffect, useState } from "react";
import {
  Music2,
  RefreshCw,
  ChevronDown,
  ExternalLink,
  Trash2,
  Loader2,
  Users,
  Wallet,
  Pencil,
  Check,
  X,
  Plus,
} from "lucide-react";
import {
  PageHeader,
  StatCard,
  EmptyState,
  Pill,
} from "@/components/affiliates/shared/ui";

interface Submission {
  id: string;
  url: string;
  createdAt: string;
}

interface Entry {
  affiliateId: string;
  name: string;
  promoCode: string;
  count: number;
  hit: boolean;
  streakMonth: number;
  reward: number;
  submissions: Submission[];
}

interface Payload {
  period: "current" | "previous";
  cycleLabel: string;
  cycleDays: number;
  daysLeft: number;
  goal: number;
  ladder: number[];
  totalSubmissions: number;
  totalBonus: number;
  entries: Entry[];
}

type Period = "current" | "previous";

export default function AdminTikTokPage() {
  const [data, setData] = useState<Payload | null>(null);
  const [period, setPeriod] = useState<Period>("current");
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState<string | null>(null);
  const [deleting, setDeleting] = useState<string | null>(null);
  // Ladder editing — values as strings so the inputs stay friendly.
  const [editingLadder, setEditingLadder] = useState(false);
  const [ladderDraft, setLadderDraft] = useState<string[]>([]);
  const [ladderSaving, setLadderSaving] = useState(false);
  const [ladderError, setLadderError] = useState<string | null>(null);

  const beginRead = useLatestRead();
  const [readError, setReadError] = useState<string | null>(null);
  const load = useCallback(async (p: Period) => {
    setLoading(true);
    const request = beginRead();
    setReadError(null); setData(null);
    try {
      const res = await fetch(`/api/affiliates/admin/tiktok?period=${encodeURIComponent(p)}`, {
        credentials: "include", cache: "no-store", signal: request.signal,
      });
      if (!res.ok) throw new Error("Could not load data. Please retry.");
      if (res.ok) {
        const json = await res.json();
        if (!request.isCurrent()) return;
        if (json?.ok) setData(json as Payload);
      }
    } catch {
      if (request.isCurrent()) setReadError("Could not load data. Please retry.");
    } finally {
      if (!request.isCurrent()) return;
      setLoading(false);
    }
  }, [beginRead]);

  useEffect(() => {
    void load(period);
  }, [load, period]);

  const removeSubmission = useCallback(
    async (id: string) => {
      if (!window.confirm("Remove this submission? It comes off the affiliate's monthly count.")) {
        return;
      }
      setDeleting(id);
      try {
        const res = await nonproviderMutationFetch(`/api/affiliates/admin/tiktok/${id}`, {
          method: "DELETE",
          credentials: "include",
        });
        if (res.ok) await load(period);
      } finally {
        setDeleting(null);
      }
    },
    [load, period]
  );

  function startEditingLadder() {
    setLadderDraft((data?.ladder ?? [100]).map((n) => String(n)));
    setLadderError(null);
    setEditingLadder(true);
  }

  async function saveLadder() {
    const amounts = ladderDraft.map((v) => Number(v));
    if (amounts.some((n) => !Number.isFinite(n) || n <= 0)) {
      setLadderError("Enter an amount above $0 for each streak cycle.");
      return;
    }
    setLadderSaving(true);
    setLadderError(null);
    try {
      const res = await nonproviderMutationFetch("/api/affiliates/admin/tiktok", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ amounts }),
      });
      const json = await res.json().catch(() => null);
      if (!res.ok || !json?.ok) {
        setLadderError(json?.error ?? "Could not save — try again.");
        return;
      }
      setEditingLadder(false);
      await load(period);
    } catch {
      setLadderError("Could not save — try again.");
    } finally {
      setLadderSaving(false);
    }
  }

  const hitCount = data?.entries.filter((e) => e.hit).length ?? 0;

  return (
    <div>
      {readError && <p role="alert">{readError} <button type="button" onClick={() => load(period)}>Retry</button></p>}
      <PageHeader
        eyebrow="TikTok bonus"
        title="TikTok submissions"
        description={
          data
            ? `Cycle ${data.cycleLabel}${
                data.period === "current"
                  ? ` — resets in ${data.daysLeft} day${data.daysLeft === 1 ? "" : "s"}`
                  : ""
              }. ${data.goal} videos per ${data.cycleDays}-day cycle earns the streak reward. Consecutive cycles climb the ladder below; a missed cycle resets the affiliate to step 1. Paid to payout balances automatically when the cycle closes.`
            : "Loading…"
        }
        actions={
          <div className="flex items-center gap-2">
            <div className="flex rounded-full bg-[#242526]/5 border border-[#242526]/10 p-1">
              {(
                [
                  { key: "current", label: "This cycle" },
                  { key: "previous", label: "Last cycle" },
                ] as const
              ).map((opt) => (
                <button
                  key={opt.key}
                  type="button"
                  onClick={() => setPeriod(opt.key)}
                  className={`px-3.5 py-1.5 rounded-full text-xs font-sans uppercase tracking-[0.12em] transition-colors ${
                    period === opt.key
                      ? "bg-[#20282c] text-white"
                      : "text-[#64717a] hover:text-[#20282c]"
                  }`}
                >
                  {opt.label}
                </button>
              ))}
            </div>
            <button
              type="button"
              onClick={() => void load(period)}
              className="inline-flex items-center gap-2 rounded-full border border-[#242526]/15 px-4 py-2 text-xs font-sans uppercase tracking-[0.12em] text-[#20282c] hover:bg-[#242526]/5 transition-colors"
            >
              <RefreshCw className={`h-3.5 w-3.5 ${loading ? "animate-spin" : ""}`} />
              Refresh
            </button>
          </div>
        }
      />

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 md:gap-4 mb-6">
        <StatCard
          icon={Music2}
          label="Submissions"
          value={data ? String(data.totalSubmissions) : "—"}
          hint={data ? data.cycleLabel : undefined}
        />
        <StatCard
          icon={Users}
          label="Hit the goal"
          value={data ? String(hitCount) : "—"}
          hint={data ? `of ${data.entries.length} active affiliates` : undefined}
        />
        <StatCard
          icon={Wallet}
          label="Bonus earned so far"
          value={data ? `$${data.totalBonus}` : "—"}
          hint="Paid when the cycle closes"
          accent
        />
      </div>

      {/* Reward ladder */}
      <div className="glass-surface rounded-lg p-5 sm:p-6 mb-8">
        <div className="flex flex-wrap items-center justify-between gap-3 mb-4">
          <div>
            <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
              Reward ladder
            </p>
            <p className="text-sm text-[#64717a] mt-1 max-w-2xl leading-relaxed">
              What a streak pays, cycle by cycle. Affiliates only reach a
              higher step by hitting {data?.goal ?? 15} videos every{" "}
              {data?.cycleDays ?? 30}-day cycle in a row — one missed cycle
              resets them to step 1. Streaks longer than the ladder keep
              paying the last step.
            </p>
          </div>
          {editingLadder ? (
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={() => void saveLadder()}
                disabled={ladderSaving}
                className="inline-flex items-center gap-1.5 rounded-full bg-[#20282c] text-white px-4 py-2 text-xs font-sans uppercase tracking-[0.12em] hover:bg-[#1E3A32] transition-colors disabled:opacity-50"
              >
                {ladderSaving ? (
                  <Loader2 className="h-3 w-3 animate-spin" />
                ) : (
                  <Check className="h-3 w-3" />
                )}
                Save
              </button>
              <button
                type="button"
                onClick={() => {
                  setEditingLadder(false);
                  setLadderError(null);
                }}
                disabled={ladderSaving}
                className="inline-flex items-center gap-1.5 rounded-full border border-[#242526]/15 px-4 py-2 text-xs font-sans uppercase tracking-[0.12em] text-[#20282c] hover:bg-[#242526]/5 transition-colors disabled:opacity-50"
              >
                <X className="h-3 w-3" />
                Cancel
              </button>
            </div>
          ) : (
            <button
              type="button"
              onClick={startEditingLadder}
              className="inline-flex items-center gap-1.5 rounded-full border border-[#242526]/15 px-4 py-2 text-xs font-sans uppercase tracking-[0.12em] text-[#20282c] hover:bg-[#242526]/5 transition-colors"
            >
              <Pencil className="h-3 w-3" />
              Edit rewards
            </button>
          )}
        </div>

        <div className="flex flex-wrap gap-2.5">
          {(editingLadder ? ladderDraft : (data?.ladder ?? [100]).map(String)).map(
            (amount, i) => (
              <div
                key={i}
                className="rounded-lg bg-[#242526]/4 border border-[#242526]/8 px-4 py-3 min-w-[110px]"
              >
                <p className="text-[10px] uppercase tracking-[0.16em] font-sans text-[#64717a]">
                  Cycle {i + 1}
                </p>
                {editingLadder ? (
                  <div className="flex items-center gap-1 mt-0.5">
                    <span className="font-sans text-lg font-semibold">$</span>
                    <input
                      type="number"
                      min="1"
                      step="10"
                      value={amount}
                      onChange={(e) =>
                        setLadderDraft((d) => {
                          const next = [...d];
                          next[i] = e.target.value;
                          return next;
                        })
                      }
                      className="w-20 bg-white/60 border border-[#20282c]/15 rounded-xl px-2 py-0.5 font-sans text-lg font-semibold focus:outline-none focus:border-[#20282c]/40"
                    />
                  </div>
                ) : (
                  <p className="font-sans text-lg font-semibold mt-0.5">
                    ${amount}
                  </p>
                )}
              </div>
            )
          )}
          {editingLadder && (
            <div className="flex flex-col justify-center gap-1.5">
              <button
                type="button"
                onClick={() =>
                  setLadderDraft((d) =>
                    d.length >= 24 ? d : [...d, d[d.length - 1] ?? "100"]
                  )
                }
                className="inline-flex items-center gap-1.5 rounded-full border border-[#242526]/15 px-3 py-1.5 text-[10px] font-sans uppercase tracking-[0.12em] text-[#20282c] hover:bg-[#242526]/5 transition-colors"
              >
                <Plus className="h-3 w-3" />
                Add cycle
              </button>
              {ladderDraft.length > 1 && (
                <button
                  type="button"
                  onClick={() => setLadderDraft((d) => d.slice(0, -1))}
                  className="inline-flex items-center gap-1.5 rounded-full border border-[#242526]/15 px-3 py-1.5 text-[10px] font-sans uppercase tracking-[0.12em] text-[#64717a] hover:bg-[#242526]/5 transition-colors"
                >
                  <X className="h-3 w-3" />
                  Remove last
                </button>
              )}
            </div>
          )}
        </div>
        {ladderError && (
          <p className="text-sm text-red-600 mt-3">{ladderError}</p>
        )}
      </div>

      {loading && !data ? (
        <div className="glass-surface rounded-lg p-10 text-center text-sm text-[#64717a]">
          <Loader2 className="h-5 w-5 animate-spin inline-block" />
        </div>
      ) : !data || data.entries.length === 0 ? (
        <EmptyState
          icon={Music2}
          title="No active affiliates"
          description="Once affiliates start submitting TikTok links they'll show up here."
        />
      ) : (
        <div className="glass-surface rounded-lg overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full min-w-[720px] text-sm">
              <thead>
                <tr className="text-left text-[10px] uppercase tracking-[0.16em] font-sans text-[#64717a] border-b border-[#242526]/8">
                  <th className="px-5 py-3.5 font-medium">Affiliate</th>
                  <th className="px-5 py-3.5 font-medium">Code</th>
                  <th className="px-5 py-3.5 font-medium">Videos</th>
                  <th className="px-5 py-3.5 font-medium">Progress</th>
                  <th className="px-5 py-3.5 font-medium">Streak</th>
                  <th className="px-5 py-3.5 font-medium">Bonus</th>
                  <th className="px-5 py-3.5 font-medium" />
                </tr>
              </thead>
              <tbody>
                {data.entries.map((entry) => {
                  const isOpen = expanded === entry.affiliateId;
                  const pct = Math.min(100, (entry.count / data.goal) * 100);
                  return (
                    <AffiliateRow
                      key={entry.affiliateId}
                      entry={entry}
                      goal={data.goal}
                      isOpen={isOpen}
                      pct={pct}
                      deleting={deleting}
                      onToggle={() =>
                        setExpanded(isOpen ? null : entry.affiliateId)
                      }
                      onDelete={removeSubmission}
                    />
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

function AffiliateRow({
  entry,
  goal,
  isOpen,
  pct,
  deleting,
  onToggle,
  onDelete,
}: {
  entry: Entry;
  goal: number;
  isOpen: boolean;
  pct: number;
  deleting: string | null;
  onToggle: () => void;
  onDelete: (id: string) => void;
}) {
  return (
    <>
      <tr
        className={`border-b border-[#242526]/6 transition-colors ${
          entry.count > 0 ? "cursor-pointer hover:bg-[#242526]/3" : ""
        }`}
        onClick={entry.count > 0 ? onToggle : undefined}
      >
        <td className="px-5 py-3.5 font-medium text-[#20282c] whitespace-nowrap">
          {entry.name}
        </td>
        <td className="px-5 py-3.5 font-sans text-xs text-[#64717a] whitespace-nowrap">
          {entry.promoCode || "—"}
        </td>
        <td className="px-5 py-3.5 font-sans font-semibold text-[#20282c] whitespace-nowrap">
          {entry.count}
          <span className="text-xs font-normal text-[#64717a]"> / {goal}</span>
        </td>
        <td className="px-5 py-3.5 w-[200px]">
          <div className="h-2 rounded-full bg-[#242526]/8 overflow-hidden">
            <div
              className={`h-full rounded-full ${
                entry.hit
                  ? "bg-gradient-to-r from-emerald-500 to-emerald-400"
                  : "bg-gradient-to-r from-[#20282c] to-[#3A5A4E]"
              }`}
              style={{ width: `${pct}%` }}
            />
          </div>
        </td>
        <td className="px-5 py-3.5 whitespace-nowrap">
          {entry.streakMonth > 1 ? (
            <Pill tone="success">Cycle {entry.streakMonth}</Pill>
          ) : (
            <span className="text-xs text-[#64717a]">Cycle 1</span>
          )}
        </td>
        <td className="px-5 py-3.5 whitespace-nowrap">
          {entry.hit ? (
            <Pill tone="dark">${entry.reward}</Pill>
          ) : (
            <span className="text-xs text-[#64717a]">
              playing for ${entry.reward}
            </span>
          )}
        </td>
        <td className="px-5 py-3.5 text-right">
          {entry.count > 0 && (
            <ChevronDown
              className={`h-4 w-4 inline-block text-[#64717a] transition-transform ${
                isOpen ? "rotate-180" : ""
              }`}
            />
          )}
        </td>
      </tr>
      {isOpen && (
        <tr className="border-b border-[#242526]/6 bg-[#242526]/2">
          <td colSpan={7} className="px-5 py-4">
            <ul className="space-y-2 max-h-72 overflow-y-auto pr-1">
              {entry.submissions.map((s) => (
                <li
                  key={s.id}
                  className="flex items-center gap-3 text-sm min-w-0"
                >
                  <span className="shrink-0 font-sans text-xs text-[#64717a] w-20">
                    {new Date(s.createdAt).toLocaleDateString("en-US", {
                      timeZone: "America/New_York",
                      month: "short",
                      day: "numeric",
                    })}
                  </span>
                  <a
                    href={s.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="truncate text-[#20282c] underline underline-offset-2 hover:no-underline inline-flex items-center gap-1.5 min-w-0"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <span className="truncate">
                      {s.url.replace(/^https?:\/\/(www\.)?/, "")}
                    </span>
                    <ExternalLink className="h-3 w-3 shrink-0 text-[#64717a]" />
                  </a>
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      onDelete(s.id);
                    }}
                    disabled={deleting === s.id}
                    className="ml-auto shrink-0 p-1.5 rounded-full text-[#64717a] hover:text-red-600 hover:bg-red-50 transition-colors disabled:opacity-50"
                    aria-label="Remove submission"
                  >
                    {deleting === s.id ? (
                      <Loader2 className="h-3.5 w-3.5 animate-spin" />
                    ) : (
                      <Trash2 className="h-3.5 w-3.5" />
                    )}
                  </button>
                </li>
              ))}
            </ul>
          </td>
        </tr>
      )}
    </>
  );
}

