        <div className="flex items-center gap-2 mb-1">
          <FlaskConical className="h-4 w-4 text-[#64717a]" />
          <p className="text-[10px] uppercase tracking-[0.18em] font-sans text-[#64717a]">
            Stacks people talk about
          </p>
