/** Card that shows a punchy one-liner and reveals the full detail on tap. */
function ExpandableCard({
  icon: Icon,
  title,
  tldr,
  body,
  step,
}: {
  icon: React.ComponentType<{ className?: string }>;
  title: string;
  tldr: string;
