          <p className="text-sm text-[#64717a] mt-1 leading-relaxed">{tldr}</p>
        </div>
        <ChevronRight
          className={`h-4 w-4 text-[#64717a] shrink-0 mt-1 transition-transform ${
            open ? "rotate-90" : ""
