        </p>
      )}

      {/* This month's submissions */}
      {data.submissions.length > 0 && (
        <div className="mt-4">
          <button
            type="button"
            onClick={() => setShowList((v) => !v)}
            className={`inline-flex items-center gap-1.5 text-xs font-sans uppercase tracking-[0.14em] ${
