            {showList ? "Hide" : "View"} your {data.submissions.length}{" "}
            submission{data.submissions.length === 1 ? "" : "s"}
          </button>
          {showList && (
            <ul
              className={`mt-3 space-y-1.5 text-sm max-h-56 overflow-y-auto pr-1 ${
                hit ? "text-white/80" : "text-[#20282c]"
