"use client";
import { useCallback, useEffect, useRef, useState } from 'react';
import { requestProgram, ProgramRequestError } from './program-api';
import { settlementPlan, payoutAttemptDisposition, type ProgramOrder, type ProgramReport } from './program-view';
const control = 'glass-surface rounded-xl px-3 py-2 text-sm border border-current/10';
const button = `${control} disabled:opacity-40 disabled:cursor-not-allowed`;
const money = (amount:number,currency:string) => `${amount.toFixed(2)} ${currency}`;
type Attempt = {idempotencyKey:string;payload:string;rejectedStatus?:number};

/** Settlement deliberately widens beyond reporting filters to net mandatory adjustments. */
export function SharedPayoutForm({affiliateId,orders,refresh,onDone}:{affiliateId:string;orders:ProgramOrder[];refresh:()=>Promise<ProgramReport>;onDone:()=>void}) {
  const [draft,setDraft]=useState<Record<string,string>>({});
  const [full,setFull]=useState<ProgramOrder[]|null>(null);
  const [method,setMethod]=useState('bank');
  const [reference,setReference]=useState('');
  const [paidAt,setPaidAt]=useState('');
  const [confirmed,setConfirmed]=useState(false);
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState('');
  const [canCorrect,setCanCorrect]=useState(false);
  const [locked,setLocked]=useState(false);
  const submitting=useRef(false);
  const pending=useRef<Attempt|null>(null);
  const storage=`iqon-payout-attempt:${affiliateId}`;
  const readFull=useCallback(async()=>{
    const data=await requestProgram(`/api/affiliates/admin/program?category=all&affiliateId=${encodeURIComponent(affiliateId)}`);
    if(!data.report || !Array.isArray(data.report.orders) || !Array.isArray(data.report.payouts))throw new Error('Complete settlement ledger unavailable.');
    return data.report as ProgramReport;
  },[affiliateId]);
  useEffect(()=>{
    let alive=true;
    void readFull().then(r=>{if(alive)setFull(r.orders);}).catch(e=>{if(alive)setError(e.message);});
    try {
      const attempt=JSON.parse(sessionStorage.getItem(storage)||'null') as Attempt|null;
      if(attempt?.payload && attempt.idempotencyKey){
        const original=JSON.parse(attempt.payload);
        pending.current=attempt;setLocked(true);
        setDraft(Object.fromEntries(original.allocations.filter((a:{amount:number})=>a.amount>0).map((a:{orderId:string;amount:number})=>[a.orderId,String(a.amount)])));
        setMethod(original.method);setReference(original.reference);
        const date=new Date(original.paidAt);setPaidAt(new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16));
        setError('An unresolved attempt was restored. Check its canonical record or retry the same token; do not make another external payment.');
      }
    }catch{setError('Previous attempt storage could not be read. Check the canonical audit before recording.');}
    return()=>{alive=false;};
  },[storage,readFull]);

  let plan:ReturnType<typeof settlementPlan>|null=null,planError='';
  if(full&&Object.values(draft).some(Boolean))try{plan=settlementPlan(full,draft,affiliateId);}catch(e){planError=e instanceof Error?e.message:'Invalid plan';}
  const displayOrders=orders.filter(o=>o.affiliateId===affiliateId&&o.outstandingAmount>0).map(o=>full?.find(r=>r.id===o.id)??o);
  const selectedCurrencies=new Set(Object.keys(draft).filter(id=>draft[id]).map(id=>full?.find(o=>o.id===id)?.currency));
  const negatives=full?.filter(o=>o.affiliateId===affiliateId&&o.outstandingAmount<0&&selectedCurrencies.has(o.currency))??[];

  async function finish(){
    sessionStorage.removeItem(storage);pending.current=null;setLocked(false);
    await refresh().catch(()=>{});onDone();
  }
  async function resolveAttempt(httpStatus?:number){
    const attempt=pending.current;if(!attempt)return;
    const r=await readFull();setFull(r.orders);
    const found=r.payouts.some(p=>p.idempotencyKey===attempt.idempotencyKey);
    const outcome=payoutAttemptDisposition(httpStatus??attempt.rejectedStatus,true,found);
    if(outcome==='recorded'){await finish();return;}
    if(outcome==='correctable'){
      attempt.rejectedStatus=httpStatus??attempt.rejectedStatus;sessionStorage.setItem(storage,JSON.stringify(attempt));
      setCanCorrect(true);setError('The server rejected this payload and the complete canonical ledger confirms no payout exists for its token. Acknowledge below to correct the allocation. No payment record was created.');
    }else setError('No record is visible yet, but the outcome is uncertain. Keep the original token and retry it; a missing record alone is not permission to start a new payment.');
  }
  function correct(){
    if(!canCorrect)return;
    sessionStorage.removeItem(storage);pending.current=null;setLocked(false);setCanCorrect(false);setConfirmed(false);
    setError('Rejected attempt cleared after canonical readback. Review updated balances and required adjustments, then confirm the corrected payment record.');
  }
  async function submit(){
    if(submitting.current||!confirmed||canCorrect)return;
    submitting.current=true;setBusy(true);setError('');
    try{
      if(!pending.current){
        if(!full||!plan)throw new Error(planError||'Load and review the full settlement plan first.');
        if(!reference.trim()||!paidAt||!Number.isFinite(new Date(paidAt).getTime()))throw new Error('Payment reference and completion time are required.');
        const latest=await readFull();setFull(latest.orders);
        const current=settlementPlan(latest.orders,draft,affiliateId);
        if(JSON.stringify(current)!==JSON.stringify(plan))throw new Error('Balances or mandatory adjustments changed. Review the updated settlement plan before confirming again.');
        const payload=JSON.stringify({affiliateId,method,reference:reference.trim(),paidAt:new Date(paidAt).toISOString(),amount:current.amount,allocations:current.allocations,orderIds:current.allocations.map(a=>a.orderId)});
        pending.current={idempotencyKey:crypto.randomUUID(),payload};
        sessionStorage.setItem(storage,JSON.stringify(pending.current));setLocked(true);
      }
      const attempt=pending.current!;
      const response=await requestProgram('/api/affiliates/admin/payouts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...JSON.parse(attempt.payload),idempotencyKey:attempt.idempotencyKey})});
      const r=await readFull();
      if(!response.payout?.id||!r.payouts.some(p=>p.id===response.payout.id&&p.idempotencyKey===attempt.idempotencyKey))throw new Error('Payment response received, but exact canonical readback is not confirmed. Retry the original token.');
      await finish();
    }catch(e){
      setError(e instanceof Error?e.message:'Payment outcome uncertain.');
      if(pending.current&&e instanceof ProgramRequestError&&(e.status===400||e.status===422)){
        pending.current.rejectedStatus=e.status;sessionStorage.setItem(storage,JSON.stringify(pending.current));
        try{await resolveAttempt(e.status);}catch{setError('Validation response received, but canonical lookup failed. Original token retained until lookup succeeds.');}
      }
    }finally{submitting.current=false;setBusy(false);}
  }
  return <form className="glass-surface rounded-lg p-5 space-y-4 border border-current/20" onSubmit={e=>{e.preventDefault();void submit();}}>
    <h3 className="font-medium">Record a payment already made</h3>
    <p className="text-sm">This does not transfer money. Choose positive entries from your report; all outstanding negative adjustments in the same currency are mandatorily included from the full lifetime ledger, even outside your category/date filters.</p>
    <fieldset disabled={busy||locked||!full} className="space-y-3">
      <div className="max-h-64 overflow-auto">{displayOrders.map(o=><label className="flex flex-wrap gap-3 items-center py-2 text-sm" key={o.id}><span className="flex-1 min-w-40">{o.orderId} · {o.category} · outstanding {money(o.outstandingAmount,o.currency)}</span><input className={`${control} w-32`} aria-label={`Allocation ${o.id}`} type="number" step="0.01" min="0.01" max={Math.max(0,o.outstandingAmount)} placeholder="Leave unpaid" value={draft[o.id]??''} onChange={e=>{setConfirmed(false);setDraft(d=>({...d,[o.id]:e.target.value}));}}/></label>)}</div>
      <div className="flex flex-wrap gap-3"><label className="text-xs grid gap-1">Paid at (your local time)<input className={control} type="datetime-local" required value={paidAt} onChange={e=>setPaidAt(e.target.value)}/></label><label className="text-xs grid gap-1">Method<select className={control} value={method} onChange={e=>setMethod(e.target.value)}>{['bank','paypal','zelle','other'].map(m=><option key={m}>{m}</option>)}</select></label><label className="text-xs grid gap-1 flex-1">External payment reference<input required className={control} value={reference} onChange={e=>setReference(e.target.value)}/></label></div>
    </fieldset>
    {!full&&<p role="status">Loading full-currency settlement plan…</p>}
    {negatives.length>0&&<aside className="border border-amber-500/40 rounded-xl p-4 text-sm"><strong>Required full negative allocations (all dates/categories)</strong>{negatives.map(o=><p key={o.id}>{o.orderId} · {o.category} · {o.createdAt.slice(0,10)} · {money(o.outstandingAmount,o.currency)}</p>)}</aside>}
    {plan&&<p className="font-medium">Net payment to record: {money(plan.amount,plan.currency)} — {plan.allocations.length} allocations, including mandatory offsets.</p>}
    {planError&&!locked&&<p role="alert">{planError}</p>}
    {locked&&pending.current&&<p className="text-xs break-all">Original immutable attempt token: {pending.current.idempotencyKey}. Retry does not change its amounts, reference or completion time.</p>}
    <label className="flex gap-2 items-start text-sm"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>I confirm this net payment was already made externally and I have reviewed all required negative adjustments.</label>
    <button className={button} disabled={busy||!confirmed||canCorrect||(!locked&&!plan)}>{busy?'Recording…':locked?'Retry same payment record':'Record completed payment'}</button>
    {locked&&<button type="button" className={`${button} ml-2`} disabled={busy} onClick={()=>void resolveAttempt().catch(()=>setError('Canonical lookup failed. Original token retained.'))}>Check recorded attempt</button>}
    {canCorrect&&<button type="button" className={button} onClick={correct}>I acknowledge no record was committed — correct rejected attempt</button>}
    {error&&<p role="alert">{error}</p>}
  </form>;
}

